// Hindi (spoken classroom Hindi, see devtools/i18n/HINDI_STYLE.md) and Hinglish for the Science Lab biology at the bench, batch BIO2 (NCERT Classes 6-10: plants, nutrition, respiration, transport, reproduction, heredity).
export const DICT_BIO2 = {
  "Ch 3 · Mindful Eating: A Path to a Healthy Body": { hi: "अध्याय 3 · सोच-समझकर खाना: स्वस्थ शरीर की राह", hg: "Ch 3 · Mindful Eating: swasth sharir ki raah" },
  "Ch 10 · Living Creatures: Exploring their Characteristics": { hi: "अध्याय 10 · सजीव: उनकी विशेषताओं की खोज", hg: "Ch 10 · Living Creatures: unki visheshtaon ki khoj" },
  "Ch 9 · Life Processes in Animals": { hi: "अध्याय 9 · जंतुओं में जैव प्रक्रम", hg: "Ch 9 · Jantuon mein jaiv prakram (Life Processes)" },
  "Ch 10 · Life Processes in Plants": { hi: "अध्याय 10 · पौधों में जैव प्रक्रम", hg: "Ch 10 · Paudhon mein jaiv prakram (Life Processes)" },
  "Ch 2 · Cell: The Building Block of Life": { hi: "अध्याय 2 · कोशिका: जीवन की इकाई", hg: "Ch 2 · Cell: jeevan ki ikai" },
  "Ch 5 · Life Processes": { hi: "अध्याय 5 · जैव प्रक्रम", hg: "Ch 5 · Life Processes (jaiv prakram)" },
  "Ch 6 · Control and Coordination": { hi: "अध्याय 6 · नियंत्रण एवं समन्वय", hg: "Ch 6 · Control aur Coordination" },
  "Put the potted plant inside the dark box and close it.": { hi: "गमले वाले पौधे को अँधेरे डिब्बे के अंदर रखिए और डिब्बा बंद कर दीजिए।", hg: "Gamle wale paudhe ko andhere dibbe ke andar rakhiye aur dibba band kar dijiye." },
  "The plant is in complete darkness.": { hi: "अब पौधा पूरे अँधेरे में है।", hg: "Ab paudha poore andhere mein hai." },
  "Take the plant out of the box and put it in the sunlight by the window.": { hi: "पौधे को डिब्बे से निकालिए और खिड़की के पास धूप में रख दीजिए।", hg: "Paudhe ko dibbe se nikaliye aur khidki ke paas dhoop mein rakh dijiye." },
  "Bright sunlight falls on the plant.": { hi: "पौधे पर तेज़ धूप पड़ रही है।", hg: "Paudhe par tez dhoop pad rahi hai." },
  "Pluck the leaf. Dip it in the boiling water for a minute or two.": { hi: "पत्ती तोड़िए। उसे एक-दो मिनट उबलते पानी में डुबोइए।", hg: "Patti todiye. Use ek-do minute ubalte paani mein duboiye." },
  "The leaf goes limp and a little darker.": { hi: "पत्ती ढीली पड़ जाती है और थोड़ी गहरी हो जाती है।", hg: "Patti dheeli pad jaati hai aur thodi gehri ho jaati hai." },
  "Boiling kills the cells and softens the leaf, so that alcohol and iodine can get into it.": { hi: "उबालने से कोशिकाएँ मर जाती हैं और पत्ती नरम हो जाती है। अब अल्कोहल और आयोडीन उसके अंदर जा सकते हैं।", hg: "Ubaalne se cells mar jaati hain aur patti naram ho jaati hai. Ab alcohol aur iodine uske andar ja sakte hain." },
  "Put the leaf into the boiling tube of alcohol and stand the tube in the hot water bath. Never heat alcohol directly on the flame.": { hi: "पत्ती को अल्कोहल वाली बॉयलिंग ट्यूब में डालिए और ट्यूब को गरम पानी के बाथ में खड़ा कीजिए। अल्कोहल को कभी सीधे लौ पर गरम मत कीजिए।", hg: "Patti ko alcohol wali boiling tube mein daaliye aur tube ko garam paani ke bath mein khada kijiye. Alcohol ko kabhi seedhe flame par garam mat kijiye." },
  "The alcohol warms up in the hot water and starts to boil gently.": { hi: "गरम पानी में अल्कोहल गरम होकर धीरे-धीरे उबलने लगता है।", hg: "Garam paani mein alcohol garam hokar dheere-dheere ubalne lagta hai." },
  "Alcohol catches fire easily, so it is heated only in a water bath.": { hi: "अल्कोहल बहुत जल्दी आग पकड़ लेता है, इसलिए उसे सिर्फ़ वॉटर बाथ में ही गरम करते हैं।", hg: "Alcohol bahut jaldi aag pakad leta hai, isliye use sirf water bath mein hi garam karte hain." },
  "Leave it in the hot alcohol until the leaf loses its green colour (time-lapse).": { hi: "पत्ती को गरम अल्कोहल में तब तक रहने दीजिए जब तक उसका हरा रंग न उतर जाए (टाइम-लैप्स)।", hg: "Patti ko garam alcohol mein tab tak rehne dijiye jab tak uska hara rang na utar jaaye (time-lapse)." },
  "The leaf turns pale yellowish-white, and the alcohol turns green.": { hi: "पत्ती फीकी, पीली-सफ़ेद हो जाती है और अल्कोहल हरा हो जाता है।", hg: "Patti pheeki, peeli-safed ho jaati hai aur alcohol hara ho jaata hai." },
  "Hot alcohol dissolves chlorophyll, the green pigment, out of the leaf. Now a colour change on the leaf will be easy to see.": { hi: "गरम अल्कोहल पत्ती का हरा रंग, यानी क्लोरोफ़िल, घोलकर बाहर निकाल देता है। अब पत्ती पर रंग का बदलना आसानी से दिखेगा।", hg: "Garam alcohol patti ka hara rang, yaani chlorophyll, gholkar bahar nikaal deta hai. Ab patti par rang ka badalna aasaani se dikhega." },
  "Take the leaf out with forceps, wash it in warm water and spread it flat in the petri dish.": { hi: "चिमटी से पत्ती निकालिए, गुनगुने पानी में धोइए और पेट्री डिश में सीधी फैला दीजिए।", hg: "Chimti se patti nikaliye, gungune paani mein dhoiye aur petri dish mein seedhi phaila dijiye." },
  "A pale, soft leaf lies flat in the dish.": { hi: "एक फीकी, नरम पत्ती डिश में सीधी फैली है।", hg: "Ek pheeki, naram patti dish mein seedhi phaili hai." },
  "Alcohol makes the leaf brittle; warm water softens it again.": { hi: "अल्कोहल से पत्ती कड़क और भुरभुरी हो जाती है; गुनगुना पानी उसे फिर नरम कर देता है।", hg: "Alcohol se patti kadak aur bhurbhuri ho jaati hai; gunguna paani use phir naram kar deta hai." },
  "Put a few drops of iodine solution on the leaf.": { hi: "पत्ती पर आयोडीन घोल की कुछ बूँदें डालिए।", hg: "Patti par iodine ghol ki kuch boondein daaliye." },
  "Do leaves need light to make starch?": { hi: "क्या पत्तियों को स्टार्च बनाने के लिए रोशनी चाहिए?", hg: "Kya pattiyon ko starch banane ke liye roshni chahiye?" },
  "To destarch a potted plant in the dark, cover part of one leaf with black paper, keep the plant in sunlight and test the leaf for starch with iodine.": { hi: "गमले के पौधे को अँधेरे में रखकर उसका स्टार्च ख़त्म करना, एक पत्ती का कुछ हिस्सा काले कागज़ से ढकना, पौधे को धूप में रखना और फिर आयोडीन से पत्ती में स्टार्च की जाँच करना।", hg: "Gamle ke paudhe ko andhere mein rakhkar uska starch khatam karna, ek patti ka kuch hissa kaale kaagaz se dhakna, paudhe ko dhoop mein rakhna aur phir iodine se patti mein starch ki jaanch karna." },
  "Photosynthesis: light is needed": { hi: "प्रकाश संश्लेषण (फ़ोटोसिंथेसिस): रोशनी ज़रूरी है", hg: "Photosynthesis: roshni zaroori hai" },
  "Leave it in the dark for two days: slide the clock on 48 hours.": { hi: "पौधे को दो दिन अँधेरे में रहने दीजिए: घड़ी को 48 घंटे आगे खिसकाइए।", hg: "Paudhe ko do din andhere mein rehne dijiye: ghadi ko 48 ghante aage khiskaiye." },
  "Two days pass. Nothing seems to change.": { hi: "दो दिन बीत गए। देखने में कुछ नहीं बदला।", hg: "Do din beet gaye. Dekhne mein kuch nahi badla." },
  "In the dark the plant cannot make food. It uses up the starch already in its leaves. Such a plant is called destarched.": { hi: "अँधेरे में पौधा भोजन नहीं बना सकता। वह पत्तियों में पहले से रखा स्टार्च ख़र्च कर देता है। ऐसे पौधे को डीस्टार्च किया हुआ (स्टार्च-रहित) पौधा कहते हैं।", hg: "Andhere mein paudha bhojan nahi bana sakta. Wo pattiyon mein pehle se rakha starch kharch kar deta hai. Aise paudhe ko destarched (starch-rahit) paudha kehte hain." },
  "Take the plant out and clip a strip of black paper across the middle of one leaf, on both sides.": { hi: "पौधे को बाहर निकालिए। एक पत्ती के बीच वाले हिस्से पर, ऊपर और नीचे दोनों तरफ़, काले कागज़ की पट्टी क्लिप से लगा दीजिए।", hg: "Paudhe ko bahar nikaliye. Ek patti ke beech wale hisse par, upar aur neeche dono taraf, kaale kaagaz ki patti clip se laga dijiye." },
  "The middle of the leaf is covered on both sides; its base and tip are open to light.": { hi: "पत्ती का बीच का हिस्सा दोनों तरफ़ से ढका है; उसका निचला सिरा और नोक खुले हैं, उन पर रोशनी पड़ेगी।", hg: "Patti ka beech ka hissa dono taraf se dhaka hai; uska nichla sira aur nok khule hain, un par roshni padegi." },
  "The covered part gets no light. The rest of the same leaf is the comparison.": { hi: "ढके हिस्से को रोशनी नहीं मिलेगी। उसी पत्ती का बाकी हिस्सा तुलना के लिए है।", hg: "Dhake hisse ko roshni nahi milegi. Usi patti ka baaki hissa tulna ke liye hai." },
  "Leave it in the sunlight for six hours: slide the clock on.": { hi: "पौधे को छह घंटे धूप में रहने दीजिए: घड़ी आगे खिसकाइए।", hg: "Paudhe ko chhah ghante dhoop mein rehne dijiye: ghadi aage khiskaiye." },
  "Six hours of bright sunlight. The leaf looks just the same.": { hi: "छह घंटे तेज़ धूप मिली। पत्ती देखने में बिल्कुल वैसी ही है।", hg: "Chhah ghante tez dhoop mili. Patti dekhne mein bilkul waisi hi hai." },
  "Starch cannot be seen; we must test for it.": { hi: "स्टार्च आँखों से नहीं दिखता; उसकी जाँच करनी पड़ती है।", hg: "Starch aankhon se nahi dikhta; uski jaanch karni padti hai." },
  "The parts that were in the light turn blue-black. The band that was under the black paper stays brown-yellow, the colour of iodine.": { hi: "जिन हिस्सों पर रोशनी पड़ी थी, वे नीले-काले हो गए। जो पट्टी काले कागज़ के नीचे थी, वह भूरी-पीली ही रही, यानी आयोडीन के रंग की।", hg: "Jin hisson par roshni padi thi, wo neele-kaale ho gaye. Jo patti kaale kaagaz ke neeche thi, wo bhoori-peeli hi rahi, yaani iodine ke rang ki." },
  "Starch turns blue-black with iodine. Starch was made only where light fell on the leaf: light is needed for photosynthesis.": { hi: "आयोडीन से स्टार्च नीला-काला हो जाता है। स्टार्च सिर्फ़ वहीं बना जहाँ पत्ती पर रोशनी पड़ी। यानी प्रकाश संश्लेषण के लिए रोशनी ज़रूरी है!", hg: "Iodine se starch neela-kaala ho jaata hai. Starch sirf wahin bana jahan patti par roshni padi. Yaani photosynthesis ke liye roshni zaroori hai!" },
  "After destarching and six hours of sunlight, the uncovered parts of the leaf turned blue-black with iodine; the part under black paper did not.": { hi: "स्टार्च ख़त्म करके छह घंटे धूप में रखने के बाद, आयोडीन से पत्ती के खुले हिस्से नीले-काले हो गए; काले कागज़ के नीचे वाला हिस्सा नहीं हुआ।", hg: "Starch khatam karke chhah ghante dhoop mein rakhne ke baad, iodine se patti ke khule hisse neele-kaale ho gaye; kaale kaagaz ke neeche wala hissa nahi hua." },
  "Leaves make starch (food) only in the parts that get light. Sunlight is necessary for photosynthesis.": { hi: "पत्तियाँ स्टार्च (भोजन) सिर्फ़ उन्हीं हिस्सों में बनाती हैं जिन्हें रोशनी मिलती है। प्रकाश संश्लेषण के लिए धूप ज़रूरी है।", hg: "Pattiyan starch (bhojan) sirf unhi hisson mein banati hain jinhe roshni milti hai. Photosynthesis ke liye dhoop zaroori hai." },
  "Never heat alcohol directly on a flame: it catches fire. Heat it only in a hot water bath, and keep the burner away.": { hi: "अल्कोहल को कभी सीधे लौ पर गरम मत कीजिए, वह आग पकड़ लेता है। उसे सिर्फ़ गरम पानी के बाथ में गरम कीजिए और बर्नर से दूर रखिए।", hg: "Alcohol ko kabhi seedhe flame par garam mat kijiye, wo aag pakad leta hai. Use sirf garam paani ke bath mein garam kijiye aur burner se door rakhiye." },
  "Why is the plant kept in the dark for two days first?": { hi: "पौधे को पहले दो दिन अँधेरे में क्यों रखते हैं?", hg: "Paudhe ko pehle do din andhere mein kyon rakhte hain?" },
  "To use up the starch already in its leaves (to destarch it).": { hi: "ताकि उसकी पत्तियों में पहले से रखा स्टार्च ख़र्च हो जाए (पौधा डीस्टार्च हो जाए)।", hg: "Taaki uski pattiyon mein pehle se rakha starch kharch ho jaaye (paudha destarch ho jaaye)." },
  "Why is the leaf boiled in alcohol?": { hi: "पत्ती को अल्कोहल में क्यों उबालते हैं?", hg: "Patti ko alcohol mein kyon ubaalte hain?" },
  "To remove the chlorophyll, so the colour of iodine can be seen.": { hi: "क्लोरोफ़िल निकालने के लिए, ताकि आयोडीन का रंग साफ़ दिखे।", hg: "Chlorophyll nikalne ke liye, taaki iodine ka rang saaf dikhe." },
  "What colour does starch give with iodine?": { hi: "आयोडीन के साथ स्टार्च कौन-सा रंग देता है?", hg: "Iodine ke saath starch kaun-sa rang deta hai?" },
  "Blue-black.": { hi: "नीला-काला।", hg: "Neela-kaala." },
  "Is chlorophyll needed to make starch? A variegated leaf": { hi: "क्या स्टार्च बनाने के लिए क्लोरोफ़िल चाहिए? हरी-सफ़ेद (चितकबरी) पत्ती", hg: "Kya starch banane ke liye chlorophyll chahiye? Hari-safed (variegated) patti" },
  "To destarch a plant with green-and-white leaves, keep it in sunlight, and see with iodine which parts of a leaf made starch.": { hi: "हरी-सफ़ेद पत्तियों वाले पौधे का स्टार्च ख़त्म करना, उसे धूप में रखना, और आयोडीन से देखना कि पत्ती के किन हिस्सों ने स्टार्च बनाया।", hg: "Hari-safed pattiyon wale paudhe ka starch khatam karna, use dhoop mein rakhna, aur iodine se dekhna ki patti ke kin hisson ne starch banaya." },
  "Photosynthesis: chlorophyll is needed": { hi: "प्रकाश संश्लेषण: क्लोरोफ़िल ज़रूरी है", hg: "Photosynthesis: chlorophyll zaroori hai" },
  "Leave it in the dark for three days: slide the clock on 72 hours.": { hi: "पौधे को तीन दिन अँधेरे में रहने दीजिए: घड़ी को 72 घंटे आगे खिसकाइए।", hg: "Paudhe ko teen din andhere mein rehne dijiye: ghadi ko 72 ghante aage khiskaiye." },
  "Three days pass in the dark.": { hi: "अँधेरे में तीन दिन बीत गए।", hg: "Andhere mein teen din beet gaye." },
  "In the dark the leaves use up the starch they had. Now any starch found later must be new.": { hi: "अँधेरे में पत्तियाँ अपना सारा स्टार्च ख़र्च कर देती हैं। अब बाद में जो भी स्टार्च मिलेगा, वह नया बना हुआ होगा।", hg: "Andhere mein pattiyan apna saara starch kharch kar deti hain. Ab baad mein jo bhi starch milega, wo naya bana hua hoga." },
  "Six hours of sunlight on the green and white leaves.": { hi: "हरी-सफ़ेद पत्तियों पर छह घंटे धूप पड़ी।", hg: "Hari-safed pattiyon par chhah ghante dhoop padi." },
  "Light falls on every part of the leaf, the white parts too.": { hi: "रोशनी पत्ती के हर हिस्से पर पड़ती है, सफ़ेद हिस्सों पर भी।", hg: "Roshni patti ke har hisse par padti hai, safed hisson par bhi." },
  "Look closely at the test leaf and note where it is green and where it is white.": { hi: "जाँच वाली पत्ती को ध्यान से देखिए और लिख लीजिए कि वह कहाँ हरी है और कहाँ सफ़ेद।", hg: "Jaanch wali patti ko dhyaan se dekhiye aur likh lijiye ki wo kahan hari hai aur kahan safed." },
  "The leaf has a creamy-white border and some white patches; the rest is green.": { hi: "पत्ती का किनारा मलाई जैसा सफ़ेद है और कुछ सफ़ेद धब्बे हैं; बाकी पत्ती हरी है।", hg: "Patti ka kinara malai jaisa safed hai aur kuch safed dhabbe hain; baaki patti hari hai." },
  "The white parts have no chlorophyll. Draw the pattern, so you can compare it after the test.": { hi: "सफ़ेद हिस्सों में क्लोरोफ़िल नहीं होता। यह पैटर्न कॉपी में बना लीजिए, ताकि जाँच के बाद तुलना कर सकें।", hg: "Safed hisson mein chlorophyll nahi hota. Ye pattern copy mein bana lijiye, taaki jaanch ke baad tulna kar sakein." },
  "Only the parts that were green turn blue-black. The white border and patches stay brownish-yellow.": { hi: "सिर्फ़ वही हिस्से नीले-काले हुए जो हरे थे। सफ़ेद किनारा और धब्बे भूरे-पीले ही रहे।", hg: "Sirf wahi hisse neele-kaale hue jo hare the. Safed kinara aur dhabbe bhoore-peele hi rahe." },
  "Starch was made only where there was chlorophyll. Chlorophyll is needed for photosynthesis.": { hi: "स्टार्च सिर्फ़ वहीं बना जहाँ क्लोरोफ़िल था। प्रकाश संश्लेषण के लिए क्लोरोफ़िल ज़रूरी है।", hg: "Starch sirf wahin bana jahan chlorophyll tha. Photosynthesis ke liye chlorophyll zaroori hai." },
  "After destarching and sunlight, iodine turned only the green parts of the leaf blue-black; the white parts did not change.": { hi: "स्टार्च ख़त्म करके धूप में रखने के बाद, आयोडीन से पत्ती के सिर्फ़ हरे हिस्से नीले-काले हुए; सफ़ेद हिस्से नहीं बदले।", hg: "Starch khatam karke dhoop mein rakhne ke baad, iodine se patti ke sirf hare hisse neele-kaale hue; safed hisse nahi badle." },
  "Chlorophyll is necessary for photosynthesis: only the green parts of a leaf make starch.": { hi: "प्रकाश संश्लेषण के लिए क्लोरोफ़िल ज़रूरी है: पत्ती के सिर्फ़ हरे हिस्से ही स्टार्च बनाते हैं।", hg: "Photosynthesis ke liye chlorophyll zaroori hai: patti ke sirf hare hisse hi starch banate hain." },
  "Heat alcohol only in a water bath, never on a naked flame. Iodine stains skin and clothes.": { hi: "अल्कोहल को सिर्फ़ वॉटर बाथ में गरम कीजिए, खुली लौ पर कभी नहीं। आयोडीन से त्वचा और कपड़ों पर दाग़ पड़ जाते हैं।", hg: "Alcohol ko sirf water bath mein garam kijiye, khuli flame par kabhi nahi. Iodine se skin aur kapdon par daag pad jaate hain." },
  "Why do the white parts not turn blue-black?": { hi: "सफ़ेद हिस्से नीले-काले क्यों नहीं होते?", hg: "Safed hisse neele-kaale kyon nahi hote?" },
  "They have no chlorophyll, so they cannot make starch.": { hi: "उनमें क्लोरोफ़िल नहीं है, इसलिए वे स्टार्च नहीं बना सकते।", hg: "Unmein chlorophyll nahi hai, isliye wo starch nahi bana sakte." },
  "Why is the plant kept in the dark for three days?": { hi: "पौधे को तीन दिन अँधेरे में क्यों रखते हैं?", hg: "Paudhe ko teen din andhere mein kyon rakhte hain?" },
  "To destarch it, so that any starch found is newly made.": { hi: "उसे डीस्टार्च करने के लिए, ताकि बाद में जो स्टार्च मिले वह नया बना हुआ हो।", hg: "Use destarch karne ke liye, taaki baad mein jo starch mile wo naya bana hua ho." },
  "Name a plant with variegated leaves.": { hi: "हरी-सफ़ेद (चितकबरी) पत्तियों वाले किसी पौधे का नाम बताइए।", hg: "Hari-safed (variegated) pattiyon wale kisi paudhe ka naam bataiye." },
  "Croton, or a variegated money plant.": { hi: "क्रोटन, या चितकबरा मनी प्लांट।", hg: "Croton, ya variegated money plant." },
  "Is carbon dioxide needed? Half a leaf in a bottle of potassium hydroxide": { hi: "क्या कार्बन डाइऑक्साइड चाहिए? पोटैशियम हाइड्रॉक्साइड की बोतल में आधी पत्ती", hg: "Kya carbon dioxide chahiye? Potassium hydroxide ki bottle mein aadhi patti" },
  "To pass half of a leaf of a destarched plant into a bottle with potassium hydroxide, which takes up carbon dioxide, keep it in sunlight and test the leaf for starch.": { hi: "स्टार्च-रहित पौधे की एक पत्ती का आधा हिस्सा पोटैशियम हाइड्रॉक्साइड वाली बोतल में डालना (यह कार्बन डाइऑक्साइड सोख लेता है), पौधे को धूप में रखना और पत्ती में स्टार्च की जाँच करना।", hg: "Starch-rahit paudhe ki ek patti ka aadha hissa potassium hydroxide wali bottle mein daalna (ye carbon dioxide sokh leta hai), paudhe ko dhoop mein rakhna aur patti mein starch ki jaanch karna." },
  "Photosynthesis: carbon dioxide is needed (Moll’s half-leaf experiment)": { hi: "प्रकाश संश्लेषण: कार्बन डाइऑक्साइड ज़रूरी है (मॉल का अर्ध-पत्ती प्रयोग)", hg: "Photosynthesis: carbon dioxide zaroori hai (Moll ka half-leaf experiment)" },
  "Two days in the dark: the plant is destarched.": { hi: "अँधेरे में दो दिन: पौधा स्टार्च-रहित हो गया।", hg: "Andhere mein do din: paudha starch-rahit ho gaya." },
  "The leaves used up their old starch.": { hi: "पत्तियों ने अपना पुराना स्टार्च ख़र्च कर दिया।", hg: "Pattiyon ne apna purana starch kharch kar diya." },
  "Take the plant out. Pass the tip half of one leaf into the bottle through a split cork, without touching the potassium hydroxide, and seal the cork with Vaseline.": { hi: "पौधे को बाहर निकालिए। एक पत्ती का आगे वाला आधा हिस्सा, बीच से कटे कॉर्क के रास्ते, बोतल के अंदर डालिए। ध्यान रहे, पत्ती पोटैशियम हाइड्रॉक्साइड को न छुए। फिर कॉर्क को वैसलीन से सील कर दीजिए।", hg: "Paudhe ko bahar nikaliye. Ek patti ka aage wala aadha hissa, beech se kate cork ke raaste, bottle ke andar daaliye. Dhyaan rahe, patti potassium hydroxide ko na chhue. Phir cork ko Vaseline se seal kar dijiye." },
  "Half the leaf is inside the airtight bottle, half outside in the air.": { hi: "पत्ती का आधा हिस्सा हवा-बंद बोतल के अंदर है और आधा बाहर हवा में।", hg: "Patti ka aadha hissa hawa-band bottle ke andar hai aur aadha bahar hawa mein." },
  "Potassium hydroxide takes up all the carbon dioxide from the air inside the bottle.": { hi: "पोटैशियम हाइड्रॉक्साइड बोतल के अंदर की हवा से सारी कार्बन डाइऑक्साइड सोख लेता है।", hg: "Potassium hydroxide bottle ke andar ki hawa se saari carbon dioxide sokh leta hai." },
  "Put the plant with the bottle in sunlight for six hours: slide the clock on.": { hi: "बोतल लगे पौधे को छह घंटे धूप में रखिए: घड़ी आगे खिसकाइए।", hg: "Bottle lage paudhe ko chhah ghante dhoop mein rakhiye: ghadi aage khiskaiye." },
  "Both halves of the leaf get the same sunlight.": { hi: "पत्ती के दोनों हिस्सों को बराबर धूप मिलती है।", hg: "Patti ke dono hisson ko barabar dhoop milti hai." },
  "The only difference between the two halves is the carbon dioxide.": { hi: "दोनों हिस्सों में फ़र्क़ सिर्फ़ कार्बन डाइऑक्साइड का है।", hg: "Dono hisson mein farq sirf carbon dioxide ka hai." },
  "The half that was outside the bottle turns blue-black. The half inside the bottle stays brownish-yellow.": { hi: "बोतल के बाहर वाला हिस्सा नीला-काला हो गया। बोतल के अंदर वाला हिस्सा भूरा-पीला ही रहा।", hg: "Bottle ke bahar wala hissa neela-kaala ho gaya. Bottle ke andar wala hissa bhoora-peela hi raha." },
  "Without carbon dioxide no starch was made. Carbon dioxide is needed for photosynthesis.": { hi: "कार्बन डाइऑक्साइड के बिना स्टार्च नहीं बना। प्रकाश संश्लेषण के लिए कार्बन डाइऑक्साइड ज़रूरी है।", hg: "Carbon dioxide ke bina starch nahi bana. Photosynthesis ke liye carbon dioxide zaroori hai." },
  "Iodine turned the part of the leaf outside the bottle blue-black; the part inside the bottle, with no carbon dioxide, stayed brownish-yellow.": { hi: "आयोडीन से बोतल के बाहर वाला हिस्सा नीला-काला हुआ; बोतल के अंदर वाला हिस्सा, जिसे कार्बन डाइऑक्साइड नहीं मिली, भूरा-पीला रहा।", hg: "Iodine se bottle ke bahar wala hissa neela-kaala hua; bottle ke andar wala hissa, jise carbon dioxide nahi mili, bhoora-peela raha." },
  "Carbon dioxide is necessary for photosynthesis.": { hi: "प्रकाश संश्लेषण के लिए कार्बन डाइऑक्साइड ज़रूरी है।", hg: "Photosynthesis ke liye carbon dioxide zaroori hai." },
  "Potassium hydroxide is caustic: do not touch it. Heat alcohol only in a water bath.": { hi: "पोटैशियम हाइड्रॉक्साइड त्वचा को जला देता है, इसे छुइए मत। अल्कोहल को सिर्फ़ वॉटर बाथ में गरम कीजिए।", hg: "Potassium hydroxide skin ko jala deta hai, ise chhuiye mat. Alcohol ko sirf water bath mein garam kijiye." },
  "What does potassium hydroxide do here?": { hi: "यहाँ पोटैशियम हाइड्रॉक्साइड क्या काम करता है?", hg: "Yahan potassium hydroxide kya kaam karta hai?" },
  "It absorbs the carbon dioxide inside the bottle.": { hi: "यह बोतल के अंदर की कार्बन डाइऑक्साइड सोख लेता है।", hg: "Ye bottle ke andar ki carbon dioxide sokh leta hai." },
  "Why is the cork sealed with Vaseline?": { hi: "कॉर्क को वैसलीन से सील क्यों करते हैं?", hg: "Cork ko Vaseline se seal kyon karte hain?" },
  "To make it airtight, so that air with carbon dioxide cannot get in.": { hi: "उसे हवा-बंद करने के लिए, ताकि कार्बन डाइऑक्साइड वाली हवा अंदर न जा सके।", hg: "Use hawa-band karne ke liye, taaki carbon dioxide wali hawa andar na ja sake." },
  "Which part of the leaf was the control?": { hi: "पत्ती का कौन-सा हिस्सा कंट्रोल (तुलना वाला) था?", hg: "Patti ka kaun-sa hissa control tha?" },
  "The half outside the bottle.": { hi: "बोतल के बाहर वाला आधा हिस्सा।", hg: "Bottle ke bahar wala aadha hissa." },
  "Plants give out water vapour: a polythene bag over a shoot": { hi: "पौधे भाप छोड़ते हैं: टहनी पर पॉलीथीन की थैली", hg: "Paudhe bhaap chhodte hain: tehni par polythene ki thaili" },
  "To cover a leafy shoot and a shoot without leaves with polythene bags, keep them in sunlight and see which bag collects water.": { hi: "पत्तियों वाली एक टहनी और बिना पत्तियों वाली एक टहनी को पॉलीथीन की थैलियों से ढकना, उन्हें धूप में रखना और देखना कि किस थैली में पानी जमा होता है।", hg: "Pattiyon wali ek tehni aur bina pattiyon wali ek tehni ko polythene ki thailiyon se dhakna, unhe dhoop mein rakhna aur dekhna ki kis thaili mein paani jama hota hai." },
  "Transpiration": { hi: "वाष्पोत्सर्जन (ट्रांसपिरेशन)", hg: "Transpiration (vashpotsarjan)" },
  "Water both plants. Then slip a polythene bag over the leafy shoot of plant A and tie it round the stem.": { hi: "दोनों पौधों को पानी दीजिए। फिर पौधे A की पत्तियों वाली टहनी पर पॉलीथीन की थैली चढ़ाइए और उसे तने के चारों ओर बाँध दीजिए।", hg: "Dono paudhon ko paani dijiye. Phir paudhe A ki pattiyon wali tehni par polythene ki thaili chadhaiye aur use tane ke chaaron or baandh dijiye." },
  "The bag covers all the leaves of plant A. It is clear and dry inside.": { hi: "थैली ने पौधे A की सारी पत्तियाँ ढक लीं। अंदर से वह साफ़ और सूखी है।", hg: "Thaili ne paudhe A ki saari pattiyan dhak leen. Andar se wo saaf aur sookhi hai." },
  "Tying the bag round the stem keeps the water from the soil out: only water from the shoot can get in.": { hi: "थैली तने पर बाँधने से मिट्टी का पानी अंदर नहीं आता: अंदर सिर्फ़ टहनी से निकला पानी ही आ सकता है।", hg: "Thaili tane par baandhne se mitti ka paani andar nahi aata: andar sirf tehni se nikla paani hi aa sakta hai." },
  "Do the same for plant B, whose leaves have been cut off.": { hi: "यही काम पौधे B के साथ कीजिए, जिसकी पत्तियाँ काट दी गई हैं।", hg: "Yahi kaam paudhe B ke saath kijiye, jiski pattiyan kaat di gayi hain." },
  "The bag over plant B covers only a bare stem.": { hi: "पौधे B की थैली में सिर्फ़ एक नंगा तना है।", hg: "Paudhe B ki thaili mein sirf ek nanga tana hai." },
  "Plant B is the control: the same in every way except for the leaves.": { hi: "पौधा B कंट्रोल है: पत्तियों को छोड़कर बाकी सब कुछ एक जैसा है।", hg: "Paudha B control hai: pattiyon ko chhodkar baaki sab kuch ek jaisa hai." },
  "Put both plants in the sunlight.": { hi: "दोनों पौधों को धूप में रख दीजिए।", hg: "Dono paudhon ko dhoop mein rakh dijiye." },
  "Both plants stand in bright sunlight.": { hi: "दोनों पौधे तेज़ धूप में हैं।", hg: "Dono paudhe tez dhoop mein hain." },
  "Leave them for three hours: slide the clock on.": { hi: "उन्हें तीन घंटे ऐसे ही रहने दीजिए: घड़ी आगे खिसकाइए।", hg: "Unhe teen ghante aise hi rehne dijiye: ghadi aage khiskaiye." },
  "The inside of bag A becomes misty.": { hi: "थैली A अंदर से धुँधली होने लगती है।", hg: "Thaili A andar se dhundhli hone lagti hai." },
  "Water vapour comes out of the leaves and condenses on the cooler bag.": { hi: "पत्तियों से भाप निकलती है और ठंडी थैली पर जमकर पानी बन जाती है।", hg: "Pattiyon se bhaap nikalti hai aur thandi thaili par jamkar paani ban jaati hai." },
  "Look closely at the inside of both bags.": { hi: "दोनों थैलियों के अंदर ध्यान से देखिए।", hg: "Dono thailiyon ke andar dhyaan se dekhiye." },
  "Bag A is covered with drops of water inside. Bag B is almost dry.": { hi: "थैली A अंदर से पानी की बूँदों से भर गई है। थैली B लगभग सूखी है।", hg: "Thaili A andar se paani ki boondon se bhar gayi hai. Thaili B lagbhag sookhi hai." },
  "Plants lose water as vapour, mostly through the stomata of their leaves. This is transpiration.": { hi: "पौधे भाप के रूप में पानी छोड़ते हैं, ज़्यादातर पत्तियों के स्टोमेटा (रंध्रों) से। इसे वाष्पोत्सर्जन कहते हैं।", hg: "Paudhe bhaap ke roop mein paani chhodte hain, zyadatar pattiyon ke stomata se. Ise transpiration kehte hain." },
  "After three hours in sunlight, drops of water collected inside the bag over the leafy shoot; the bag over the leafless shoot stayed almost dry.": { hi: "तीन घंटे धूप में रहने के बाद, पत्तियों वाली टहनी की थैली में पानी की बूँदें जमा हो गईं; बिना पत्तियों वाली टहनी की थैली लगभग सूखी रही।", hg: "Teen ghante dhoop mein rehne ke baad, pattiyon wali tehni ki thaili mein paani ki boondein jama ho gayin; bina pattiyon wali tehni ki thaili lagbhag sookhi rahi." },
  "Plants give out water vapour from their leaves. This loss of water is called transpiration.": { hi: "पौधे अपनी पत्तियों से भाप छोड़ते हैं। पानी के इस तरह निकलने को वाष्पोत्सर्जन कहते हैं।", hg: "Paudhe apni pattiyon se bhaap chhodte hain. Paani ke is tarah nikalne ko transpiration kehte hain." },
  "Do not leave the bags on for days: the leaves need air.": { hi: "थैलियाँ कई दिन तक लगी मत छोड़िए: पत्तियों को हवा चाहिए।", hg: "Thailiyan kai din tak lagi mat chhodiye: pattiyon ko hawa chahiye." },
  "Through which openings does a leaf lose water?": { hi: "पत्ती किन छेदों से पानी छोड़ती है?", hg: "Patti kin chhedon se paani chhodti hai?" },
  "Through the stomata.": { hi: "स्टोमेटा (रंध्रों) से।", hg: "Stomata se." },
  "Why was the bag tied round the stem and not over the pot?": { hi: "थैली गमले पर नहीं, तने पर क्यों बाँधी गई?", hg: "Thaili gamle par nahi, tane par kyon baandhi gayi?" },
  "So that water evaporating from the soil does not get into the bag.": { hi: "ताकि मिट्टी से उड़ने वाला पानी थैली में न आए।", hg: "Taaki mitti se udne wala paani thaili mein na aaye." },
  "Name one use of transpiration to the plant.": { hi: "वाष्पोत्सर्जन से पौधे को एक फ़ायदा बताइए।", hg: "Transpiration se paudhe ko ek fayda bataiye." },
  "It pulls water up from the roots, and it cools the leaves.": { hi: "इससे जड़ों से पानी ऊपर खिंचता है, और पत्तियाँ ठंडी रहती हैं।", hg: "Isse jadon se paani upar khinchta hai, aur pattiyan thandi rehti hain." },
  "Water climbs the stem: a white sadabahar twig in red ink": { hi: "पानी तने में ऊपर चढ़ता है: लाल स्याही में सफ़ेद सदाबहार की टहनी", hg: "Paani tane mein upar chadhta hai: laal syahi mein safed sadabahar ki tehni" },
  "To stand a twig of white sadabahar in red-coloured water and follow the colour up the stem into its leaves and flowers, then cut across the stem.": { hi: "सफ़ेद सदाबहार की टहनी को लाल रंग वाले पानी में खड़ा करना, रंग को तने से पत्तियों और फूलों तक चढ़ते देखना, फिर तने को आड़ा काटकर देखना।", hg: "Safed sadabahar ki tehni ko laal rang wale paani mein khada karna, rang ko tane se pattiyon aur phoolon tak chadhte dekhna, phir tane ko aada kaatkar dekhna." },
  "Transport of water in plants (xylem)": { hi: "पौधों में पानी का परिवहन (ज़ाइलम)", hg: "Paudhon mein paani ka transport (xylem)" },
  "Pour about 10 mL of red ink into the tumbler of water.": { hi: "पानी के गिलास में लगभग 10 मिलीलीटर लाल स्याही डालिए।", hg: "Paani ke gilaas mein lagbhag 10 mL laal syahi daaliye." },
  "The water turns deep red.": { hi: "पानी गहरा लाल हो जाता है।", hg: "Paani gehra laal ho jaata hai." },
  "Cut the base of the twig slantwise under water, and stand the twig in the red water.": { hi: "पानी के अंदर ही टहनी का निचला सिरा तिरछा काटिए, और टहनी को लाल पानी में खड़ा कर दीजिए।", hg: "Paani ke andar hi tehni ka nichla sira tirchha kaatiye, aur tehni ko laal paani mein khada kar dijiye." },
  "The twig stands in the red water; its flowers are white.": { hi: "टहनी लाल पानी में खड़ी है; उसके फूल सफ़ेद हैं।", hg: "Tehni laal paani mein khadi hai; uske phool safed hain." },
  "A slanting cut under water gives a large surface and keeps air bubbles out of the stem.": { hi: "पानी के अंदर तिरछा काटने से कटी सतह बड़ी होती है और तने में हवा के बुलबुले नहीं घुसते।", hg: "Paani ke andar tirchha kaatne se kati satah badi hoti hai aur tane mein hawa ke bulbule nahi ghuste." },
  "Leave it for a day: slide the clock on 24 hours.": { hi: "इसे एक दिन ऐसे ही रहने दीजिए: घड़ी को 24 घंटे आगे खिसकाइए।", hg: "Ise ek din aise hi rehne dijiye: ghadi ko 24 ghante aage khiskaiye." },
  "Slowly, red lines appear in the petals and the veins of the leaves.": { hi: "धीरे-धीरे पंखुड़ियों में और पत्तियों की नसों में लाल धारियाँ दिखने लगती हैं।", hg: "Dheere-dheere pankhudiyon mein aur pattiyon ki nason mein laal dhaariyan dikhne lagti hain." },
  "The red water has climbed up the stem and spread into the leaves and flowers.": { hi: "लाल पानी तने से ऊपर चढ़कर पत्तियों और फूलों में फैल गया है।", hg: "Laal paani tane se upar chadhkar pattiyon aur phoolon mein phail gaya hai." },
  "Look closely at a flower and a leaf.": { hi: "एक फूल और एक पत्ती को ध्यान से देखिए।", hg: "Ek phool aur ek patti ko dhyaan se dekhiye." },
  "The white petals have turned pink-red, darkest along their veins, and the leaf veins are red too.": { hi: "सफ़ेद पंखुड़ियाँ गुलाबी-लाल हो गईं, नसों के पास सबसे गहरी। पत्तियों की नसें भी लाल हो गई हैं।", hg: "Safed pankhudiyan gulabi-laal ho gayin, nason ke paas sabse gehri. Pattiyon ki nasein bhi laal ho gayi hain." },
  "Water travels through narrow tubes, the xylem, from the stem into the veins of every leaf and petal.": { hi: "पानी पतली-पतली नलियों से, जिन्हें ज़ाइलम कहते हैं, तने से हर पत्ती और पंखुड़ी की नसों तक पहुँचता है।", hg: "Paani patli-patli naliyon se, jinhe xylem kehte hain, tane se har patti aur pankhudi ki nason tak pahunchta hai." },
  "Take the twig out, cut a thin slice across its stem with a blade and look at the slice through the magnifying glass.": { hi: "टहनी बाहर निकालिए, ब्लेड से उसके तने का एक पतला, आड़ा टुकड़ा काटिए और उसे आवर्धक लेंस से देखिए।", hg: "Tehni bahar nikaliye, blade se uske tane ka ek patla, aada tukda kaatiye aur use magnifying glass se dekhiye." },
  "A ring of red dots near the edge of the slice; the centre is pale.": { hi: "टुकड़े के किनारे के पास लाल बिंदुओं का एक घेरा है; बीच का हिस्सा फीका है।", hg: "Tukde ke kinare ke paas laal binduon ka ek ghera hai; beech ka hissa pheeka hai." },
  "Each red dot is a bundle of xylem tubes that carried the red water. In a dicot stem they lie in a ring.": { hi: "हर लाल बिंदु ज़ाइलम नलियों का एक गुच्छा है, जिसने लाल पानी ऊपर पहुँचाया। द्विबीजपत्री (डाइकॉट) तने में ये एक घेरे में होते हैं।", hg: "Har laal bindu xylem naliyon ka ek guchha hai, jisne laal paani upar pahunchaya. Dicot tane mein ye ek ghere mein hote hain." },
  "After a day in red water the white petals and the leaf veins turned red, and a slice of the stem showed a ring of red dots.": { hi: "लाल पानी में एक दिन रहने के बाद सफ़ेद पंखुड़ियाँ और पत्तियों की नसें लाल हो गईं, और तने के टुकड़े में लाल बिंदुओं का घेरा दिखा।", hg: "Laal paani mein ek din rehne ke baad safed pankhudiyan aur pattiyon ki nasein laal ho gayin, aur tane ke tukde mein laal binduon ka ghera dikha." },
  "Water moves up a plant through the xylem tubes of the stem to the leaves and flowers.": { hi: "पौधे में पानी तने की ज़ाइलम नलियों से होकर पत्तियों और फूलों तक ऊपर जाता है।", hg: "Paudhe mein paani tane ki xylem naliyon se hokar pattiyon aur phoolon tak upar jaata hai." },
  "Handle the blade carefully; cut away from your fingers.": { hi: "ब्लेड सावधानी से पकड़िए; उँगलियों से दूर की तरफ़ काटिए।", hg: "Blade saavdhaani se pakadiye; ungliyon se door ki taraf kaatiye." },
  "Which tissue carries water up the stem?": { hi: "कौन-सा ऊतक (टिशू) तने में पानी ऊपर ले जाता है?", hg: "Kaun-sa tissue tane mein paani upar le jaata hai?" },
  "Xylem.": { hi: "ज़ाइलम।", hg: "Xylem." },
  "Why is the stem cut under water?": { hi: "तने को पानी के अंदर क्यों काटते हैं?", hg: "Tane ko paani ke andar kyon kaatte hain?" },
  "So that air bubbles do not block the xylem tubes.": { hi: "ताकि हवा के बुलबुले ज़ाइलम नलियों को बंद न कर दें।", hg: "Taaki hawa ke bulbule xylem naliyon ko band na kar dein." },
  "How are the red dots arranged in the slice?": { hi: "टुकड़े में लाल बिंदु किस तरह लगे हैं?", hg: "Tukde mein laal bindu kis tarah lage hain?" },
  "In a ring.": { hi: "एक घेरे में।", hg: "Ek ghere mein." },
  "What does a plant need to stay healthy? Light and water": { hi: "पौधे को स्वस्थ रहने के लिए क्या चाहिए? रोशनी और पानी", hg: "Paudhe ko swasth rehne ke liye kya chahiye? Roshni aur paani" },
  "To grow three saplings for two weeks, one with sunlight and water, one without water, one without light, and compare them.": { hi: "तीन छोटे पौधों को दो हफ़्ते उगाना: एक को धूप और पानी दोनों, एक को पानी नहीं, एक को रोशनी नहीं, और फिर उनकी तुलना करना।", hg: "Teen chhote paudhon ko do hafte ugaana: ek ko dhoop aur paani dono, ek ko paani nahi, ek ko roshni nahi, aur phir unki tulna karna." },
  "Needs of plants: light and water": { hi: "पौधों की ज़रूरतें: रोशनी और पानी", hg: "Paudhon ki zaroortein: roshni aur paani" },
  "Put saplings A and B in the sunlight, and sapling C inside the dark box.": { hi: "पौधे A और B को धूप में रखिए, और पौधे C को अँधेरे डिब्बे के अंदर।", hg: "Paudhe A aur B ko dhoop mein rakhiye, aur paudhe C ko andhere dibbe ke andar." },
  "A and B stand in the sunlight; C is in the dark.": { hi: "A और B धूप में हैं; C अँधेरे में है।", hg: "A aur B dhoop mein hain; C andhere mein hai." },
  "Give A and C 50 mL of water each. Give B no water.": { hi: "A और C को 50-50 मिलीलीटर पानी दीजिए। B को पानी मत दीजिए।", hg: "A aur C ko 50-50 mL paani dijiye. B ko paani mat dijiye." },
  "The soil of A and C is wet; B stays dry.": { hi: "A और C की मिट्टी गीली है; B की सूखी है।", hg: "A aur C ki mitti geeli hai; B ki sookhi hai." },
  "A gets both light and water: it is the control.": { hi: "A को रोशनी और पानी दोनों मिलते हैं: यह कंट्रोल है।", hg: "A ko roshni aur paani dono milte hain: ye control hai." },
  "Do the same every day for two weeks: slide the clock on 14 days.": { hi: "दो हफ़्ते तक रोज़ यही कीजिए: घड़ी को 14 दिन आगे खिसकाइए।", hg: "Do hafte tak roz yahi kijiye: ghadi ko 14 din aage khiskaiye." },
  "Two weeks pass.": { hi: "दो हफ़्ते बीत गए।", hg: "Do hafte beet gaye." },
  "Take C out of the box and compare the three saplings.": { hi: "C को डिब्बे से निकालिए और तीनों पौधों की तुलना कीजिए।", hg: "C ko dibbe se nikaliye aur teeno paudhon ki tulna kijiye." },
  "A is green, healthy and taller. B has wilted, its leaves dry and yellow-brown. C is tall and thin with small pale yellow leaves.": { hi: "A हरा, स्वस्थ और लंबा हो गया। B मुरझा गया, उसकी पत्तियाँ सूखकर पीली-भूरी हो गईं। C लंबा और पतला है, उसकी पत्तियाँ छोटी और फीकी पीली हैं।", hg: "A hara, swasth aur lamba ho gaya. B murjha gaya, uski pattiyan sookhkar peeli-bhoori ho gayin. C lamba aur patla hai, uski pattiyan chhoti aur pheeki peeli hain." },
  "A plant needs water and sunlight. Without water it wilts and dies; without light it cannot make food or chlorophyll, so it grows thin and pale.": { hi: "पौधे को पानी और धूप दोनों चाहिए। पानी के बिना वह मुरझाकर मर जाता है। रोशनी के बिना वह न भोजन बना पाता है, न क्लोरोफ़िल, इसलिए पतला और फीका हो जाता है।", hg: "Paudhe ko paani aur dhoop dono chahiye. Paani ke bina wo murjhakar mar jaata hai. Roshni ke bina wo na bhojan bana paata hai, na chlorophyll, isliye patla aur pheeka ho jaata hai." },
  "With sunlight and water, sapling A grew green and tall. Without water, B wilted and dried. Without light, C grew long, thin and pale.": { hi: "धूप और पानी पाकर पौधा A हरा और लंबा हुआ। पानी के बिना B मुरझाकर सूख गया। रोशनी के बिना C लंबा, पतला और फीका हो गया।", hg: "Dhoop aur paani paakar paudha A hara aur lamba hua. Paani ke bina B murjhakar sookh gaya. Roshni ke bina C lamba, patla aur pheeka ho gaya." },
  "Plants need both water and sunlight to make food and stay healthy.": { hi: "भोजन बनाने और स्वस्थ रहने के लिए पौधों को पानी और धूप, दोनों चाहिए।", hg: "Bhojan banane aur swasth rehne ke liye paudhon ko paani aur dhoop, dono chahiye." },
  "Water plants gently; do not flood the pot.": { hi: "पौधों को धीरे-धीरे पानी दीजिए; गमले में पानी भर मत दीजिए।", hg: "Paudhon ko dheere-dheere paani dijiye; gamle mein paani bhar mat dijiye." },
  "Why did C turn pale yellow?": { hi: "C फीका पीला क्यों हो गया?", hg: "C pheeka peela kyon ho gaya?" },
  "Without light it could not make chlorophyll or food.": { hi: "रोशनी के बिना वह क्लोरोफ़िल और भोजन नहीं बना सका।", hg: "Roshni ke bina wo chlorophyll aur bhojan nahi bana saka." },
  "Which sapling was the control?": { hi: "कौन-सा पौधा कंट्रोल था?", hg: "Kaun-sa paudha control tha?" },
  "A, which got both sunlight and water.": { hi: "A, जिसे धूप और पानी दोनों मिले।", hg: "A, jise dhoop aur paani dono mile." },
  "Why did B wilt?": { hi: "B क्यों मुरझाया?", hg: "B kyon murjhaya?" },
  "Without water its cells lost their firmness and the leaves drooped.": { hi: "पानी के बिना उसकी कोशिकाओं का कसाव ख़त्म हो गया और पत्तियाँ लटक गईं।", hg: "Paani ke bina uski cells ka kasaav khatam ho gaya aur pattiyan latak gayin." },
  "Which foods have starch? The iodine test": { hi: "किन खानों में स्टार्च है? आयोडीन से जाँच", hg: "Kin khaanon mein starch hai? Iodine se jaanch" },
  "To put a few drops of dilute iodine solution on five foods and find out from the colour which of them contain starch.": { hi: "पाँच खानों पर पतले आयोडीन घोल की कुछ बूँदें डालना और रंग देखकर पता करना कि किनमें स्टार्च है।", hg: "Paanch khaanon par patle iodine ghol ki kuch boondein daalna aur rang dekhkar pata karna ki kinmein starch hai." },
  "Test for starch": { hi: "स्टार्च की जाँच", hg: "Starch ki jaanch" },
  "Iodine turned blue-black on potato, boiled rice and bread; it stayed yellowish-brown on apple and cucumber.": { hi: "आलू, उबले चावल और ब्रेड पर आयोडीन नीला-काला हो गया; सेब और खीरे पर वह पीला-भूरा ही रहा।", hg: "Aloo, ubale chawal aur bread par iodine neela-kaala ho gaya; seb aur kheere par wo peela-bhoora hi raha." },
  "Potato, rice and bread contain starch; ripe apple has very little and cucumber has none. Starch is a carbohydrate, an energy-giving nutrient.": { hi: "आलू, चावल और ब्रेड में स्टार्च है; पके सेब में बहुत कम है और खीरे में बिल्कुल नहीं। स्टार्च एक कार्बोहाइड्रेट है, यानी ऊर्जा देने वाला पोषक तत्व।", hg: "Aloo, chawal aur bread mein starch hai; pake seb mein bahut kam hai aur kheere mein bilkul nahi. Starch ek carbohydrate hai, yaani energy dene wala poshak tatva." },
  "Iodine stains skin and clothes and is not to be tasted. Do not eat food used in the lab.": { hi: "आयोडीन से त्वचा और कपड़ों पर दाग़ लगते हैं, और इसे चखना नहीं है। लैब में इस्तेमाल हुआ खाना मत खाइए।", hg: "Iodine se skin aur kapdon par daag lagte hain, aur ise chakhna nahi hai. Lab mein istemaal hua khaana mat khaiye." },
  "What colour does iodine give with starch?": { hi: "स्टार्च के साथ आयोडीन कौन-सा रंग देता है?", hg: "Starch ke saath iodine kaun-sa rang deta hai?" },
  "Name two foods rich in starch.": { hi: "स्टार्च से भरपूर दो खानों के नाम बताइए।", hg: "Starch se bharpoor do khaanon ke naam bataiye." },
  "Potato and rice (also wheat, bread).": { hi: "आलू और चावल (गेहूँ और ब्रेड भी)।", hg: "Aloo aur chawal (gehun aur bread bhi)." },
  "To which group of nutrients does starch belong?": { hi: "स्टार्च किस तरह के पोषक तत्वों में आता है?", hg: "Starch kis tarah ke poshak tatvon mein aata hai?" },
  "Carbohydrates.": { hi: "कार्बोहाइड्रेट।", hg: "Carbohydrates." },
  "Which foods have fat? The paper test": { hi: "किन खानों में वसा (फ़ैट) है? कागज़ से जाँच", hg: "Kin khaanon mein fat hai? Kaagaz se jaanch" },
  "To press or rub foods on squares of white paper and look through them at a lamp: an oily patch shows fat.": { hi: "खानों को सफ़ेद कागज़ के टुकड़ों पर दबाना या रगड़ना, फिर कागज़ को लैंप की तरफ़ करके उसके आर-पार देखना: तेल जैसा धब्बा वसा का निशान है।", hg: "Khaanon ko safed kaagaz ke tukdon par dabaana ya ragadna, phir kaagaz ko lamp ki taraf karke uske aar-paar dekhna: tel jaisa dhabba fat ka nishaan hai." },
  "Test for fats": { hi: "वसा (फ़ैट) की जाँच", hg: "Fat ki jaanch" },
  "Put a few crushed groundnuts on paper A, fold the paper over them and press hard. Then take the nuts off.": { hi: "कागज़ A पर कुछ कुचली हुई मूँगफली रखिए, कागज़ मोड़कर उन्हें ज़ोर से दबाइए। फिर मूँगफली हटा दीजिए।", hg: "Kaagaz A par kuch kuchli hui moongphali rakhiye, kaagaz modkar unhe zor se dabaiye. Phir moongphali hata dijiye." },
  "A greasy-looking patch is left where the nuts were pressed.": { hi: "जहाँ मूँगफली दबाई थी, वहाँ चिकना-सा धब्बा रह गया।", hg: "Jahan moongphali dabaayi thi, wahan chikna-sa dhabba reh gaya." },
  "Rub a little butter on paper B.": { hi: "कागज़ B पर थोड़ा मक्खन रगड़िए।", hg: "Kaagaz B par thoda makkhan ragadiye." },
  "A greasy patch on paper B.": { hi: "कागज़ B पर चिकना धब्बा।", hg: "Kaagaz B par chikna dhabba." },
  "Put two drops of mustard oil on paper C.": { hi: "कागज़ C पर सरसों के तेल की दो बूँदें डालिए।", hg: "Kaagaz C par sarson ke tel ki do boondein daaliye." },
  "The oil soaks in and leaves a patch.": { hi: "तेल कागज़ में सोखकर धब्बा छोड़ देता है।", hg: "Tel kaagaz mein sokhkar dhabba chhod deta hai." },
  "Rub the cucumber slice on paper D.": { hi: "कागज़ D पर खीरे का टुकड़ा रगड़िए।", hg: "Kaagaz D par kheere ka tukda ragadiye." },
  "A wet patch on paper D.": { hi: "कागज़ D पर गीला धब्बा।", hg: "Kaagaz D par geela dhabba." },
  "Let the papers dry for a few minutes: slide the clock on.": { hi: "कागज़ों को कुछ मिनट सूखने दीजिए: घड़ी आगे खिसकाइए।", hg: "Kaagazon ko kuch minute sookhne dijiye: ghadi aage khiskaiye." },
  "The wet patch on D dries and disappears. The patches on A, B and C stay.": { hi: "D का गीला धब्बा सूखकर गायब हो गया। A, B और C के धब्बे बने रहे।", hg: "D ka geela dhabba sookhkar gayab ho gaya. A, B aur C ke dhabbe bane rahe." },
  "Water evaporates; fat does not.": { hi: "पानी उड़ जाता है; वसा नहीं उड़ती।", hg: "Paani ud jaata hai; fat nahi udta." },
  "Hold each paper up against the lamp and look through it.": { hi: "हर कागज़ को लैंप के सामने उठाकर उसके आर-पार देखिए।", hg: "Har kaagaz ko lamp ke saamne uthaakar uske aar-paar dekhiye." },
  "Light shines through the patches on A, B and C: they look like translucent windows. Paper D looks the same everywhere.": { hi: "A, B और C के धब्बों से रोशनी आर-पार दिखती है, जैसे छोटी पारभासी खिड़कियाँ हों। कागज़ D हर जगह एक जैसा दिखता है।", hg: "A, B aur C ke dhabbon se roshni aar-paar dikhti hai, jaise chhoti translucent khidkiyan hon. Kaagaz D har jagah ek jaisa dikhta hai." },
  "Fat (oil) leaves a lasting translucent patch on paper. Groundnuts, butter and mustard oil contain fat; cucumber does not.": { hi: "वसा (तेल) कागज़ पर हमेशा रहने वाला पारभासी धब्बा छोड़ती है। मूँगफली, मक्खन और सरसों के तेल में वसा है; खीरे में नहीं।", hg: "Fat (tel) kaagaz par hamesha rehne wala translucent dhabba chhodta hai. Moongphali, makkhan aur sarson ke tel mein fat hai; kheere mein nahi." },
  "Groundnuts, butter and mustard oil left oily patches that let light through; the cucumber left a wet patch that dried away.": { hi: "मूँगफली, मक्खन और सरसों के तेल ने ऐसे चिकने धब्बे छोड़े जिनसे रोशनी आर-पार जाती है; खीरे ने गीला धब्बा छोड़ा जो सूख गया।", hg: "Moongphali, makkhan aur sarson ke tel ne aise chikne dhabbe chhode jinse roshni aar-paar jaati hai; kheere ne geela dhabba chhoda jo sookh gaya." },
  "Groundnuts, butter and oil contain fats; cucumber does not. Fats give us a lot of energy.": { hi: "मूँगफली, मक्खन और तेल में वसा होती है; खीरे में नहीं। वसा हमें बहुत ऊर्जा देती है।", hg: "Moongphali, makkhan aur tel mein fat hota hai; kheere mein nahi. Fat humein bahut energy deta hai." },
  "Do not eat the food samples used in the lab.": { hi: "लैब में इस्तेमाल हुए खाने के नमूने मत खाइए।", hg: "Lab mein istemaal hue khaane ke samples mat khaiye." },
  "How does a fat show up on paper?": { hi: "कागज़ पर वसा कैसे पहचानी जाती है?", hg: "Kaagaz par fat kaise pehchana jaata hai?" },
  "As a translucent, oily patch that does not dry.": { hi: "एक पारभासी, चिकने धब्बे से, जो सूखता नहीं।", hg: "Ek translucent, chikne dhabbe se, jo sookhta nahi." },
  "Why do we let the paper dry before looking?": { hi: "देखने से पहले कागज़ को सूखने क्यों देते हैं?", hg: "Dekhne se pehle kaagaz ko sookhne kyon dete hain?" },
  "So that a water patch, which also looks translucent, dries away.": { hi: "ताकि पानी का धब्बा, जो पारभासी दिखता है, सूखकर हट जाए।", hg: "Taaki paani ka dhabba, jo translucent dikhta hai, sookhkar hat jaaye." },
  "Name two foods rich in fat.": { hi: "वसा से भरपूर दो खानों के नाम बताइए।", hg: "Fat se bharpoor do khaanon ke naam bataiye." },
  "Groundnuts and butter (also ghee, oil, coconut).": { hi: "मूँगफली और मक्खन (घी, तेल, नारियल भी)।", hg: "Moongphali aur makkhan (ghee, tel, nariyal bhi)." },
  "Which foods have protein? Copper sulphate and caustic soda": { hi: "किन खानों में प्रोटीन है? कॉपर सल्फ़ेट और कास्टिक सोडा से जाँच", hg: "Kin khaanon mein protein hai? Copper sulphate aur caustic soda se jaanch" },
  "To add copper sulphate solution and then caustic soda (sodium hydroxide) to four samples and look for a violet colour, the sign of protein.": { hi: "चार नमूनों में पहले कॉपर सल्फ़ेट का घोल और फिर कास्टिक सोडा (सोडियम हाइड्रॉक्साइड) डालना, और बैंगनी रंग ढूँढना, जो प्रोटीन का निशान है।", hg: "Chaar samples mein pehle copper sulphate ka ghol aur phir caustic soda (sodium hydroxide) daalna, aur baingani rang dhoondhna, jo protein ka nishaan hai." },
  "Test for proteins": { hi: "प्रोटीन की जाँच", hg: "Protein ki jaanch" },
  "Test tube A — water": { hi: "टेस्ट ट्यूब A — पानी", hg: "Test tube A — paani" },
  "Test tube B — milk mixed with water": { hi: "टेस्ट ट्यूब B — पानी मिला दूध", hg: "Test tube B — paani mila doodh" },
  "Test tube C — gram flour (besan) in water": { hi: "टेस्ट ट्यूब C — पानी में बेसन", hg: "Test tube C — paani mein besan" },
  "Test tube D — rice water (starch)": { hi: "टेस्ट ट्यूब D — चावल का पानी (माँड़, स्टार्च)", hg: "Test tube D — chawal ka paani (maand, starch)" },
  "Add two drops of copper sulphate solution to each of the four tubes.": { hi: "चारों ट्यूबों में कॉपर सल्फ़ेट घोल की दो-दो बूँदें डालिए।", hg: "Chaaron tubes mein copper sulphate ghol ki do-do boondein daaliye." },
  "Each sample turns very slightly blue.": { hi: "हर नमूना हल्का-सा नीला हो जाता है।", hg: "Har sample halka-sa neela ho jaata hai." },
  "Now add ten drops of sodium hydroxide solution to each tube and shake gently.": { hi: "अब हर ट्यूब में सोडियम हाइड्रॉक्साइड घोल की दस-दस बूँदें डालिए और हल्के से हिलाइए।", hg: "Ab har tube mein sodium hydroxide ghol ki das-das boondein daaliye aur halke se hilaiye." },
  "Pale blue cloudiness appears in every tube.": { hi: "हर ट्यूब में हल्का नीला धुंधलापन आ जाता है।", hg: "Har tube mein halka neela dhundhlapan aa jaata hai." },
  "Copper sulphate and sodium hydroxide make light blue copper hydroxide.": { hi: "कॉपर सल्फ़ेट और सोडियम हाइड्रॉक्साइड मिलकर हल्का नीला कॉपर हाइड्रॉक्साइड बनाते हैं।", hg: "Copper sulphate aur sodium hydroxide milkar halka neela copper hydroxide banate hain." },
  "Let the tubes stand for two or three minutes and compare their colours.": { hi: "ट्यूबों को दो-तीन मिनट रखा रहने दीजिए और उनके रंगों की तुलना कीजिए।", hg: "Tubes ko do-teen minute rakha rehne dijiye aur unke rangon ki tulna kijiye." },
  "B (milk) and C (gram flour) turn violet. A (water) and D (rice water) stay light blue.": { hi: "B (दूध) और C (बेसन) बैंगनी हो गए। A (पानी) और D (चावल का पानी) हल्के नीले ही रहे।", hg: "B (doodh) aur C (besan) baingani ho gaye. A (paani) aur D (chawal ka paani) halke neele hi rahe." },
  "A violet colour shows protein. Milk and pulses such as gram are rich in protein; water and rice water have hardly any.": { hi: "बैंगनी रंग बताता है कि प्रोटीन है। दूध और चने जैसी दालों में ख़ूब प्रोटीन होता है; पानी और चावल के पानी में लगभग नहीं।", hg: "Baingani rang batata hai ki protein hai. Doodh aur chane jaisi daalon mein khoob protein hota hai; paani aur chawal ke paani mein lagbhag nahi." },
  "With copper sulphate and sodium hydroxide, milk and gram flour turned violet; water and rice water stayed light blue.": { hi: "कॉपर सल्फ़ेट और सोडियम हाइड्रॉक्साइड से दूध और बेसन बैंगनी हो गए; पानी और चावल का पानी हल्के नीले रहे।", hg: "Copper sulphate aur sodium hydroxide se doodh aur besan baingani ho gaye; paani aur chawal ka paani halke neele rahe." },
  "Milk and gram (pulses) contain protein. Proteins are body-building foods.": { hi: "दूध और चने (दालों) में प्रोटीन होता है। प्रोटीन शरीर बनाने वाला भोजन है।", hg: "Doodh aur chane (daalon) mein protein hota hai. Protein sharir banane wala bhojan hai." },
  "Sodium hydroxide (caustic soda) burns skin and eyes: use a dropper, wear goggles, and wash off any splash with plenty of water.": { hi: "सोडियम हाइड्रॉक्साइड (कास्टिक सोडा) त्वचा और आँखों को जला देता है: ड्रॉपर से डालिए, चश्मा पहनिए, और छींटा पड़े तो ख़ूब पानी से धो डालिए।", hg: "Sodium hydroxide (caustic soda) skin aur aankhon ko jala deta hai: dropper se daaliye, goggles pehniye, aur chheenta pade to khoob paani se dho daaliye." },
  "Which colour shows that protein is present?": { hi: "कौन-सा रंग बताता है कि प्रोटीन मौजूद है?", hg: "Kaun-sa rang batata hai ki protein maujood hai?" },
  "Violet (purple).": { hi: "बैंगनी।", hg: "Baingani (violet)." },
  "Why is a tube of plain water tested too?": { hi: "सादे पानी वाली ट्यूब की भी जाँच क्यों करते हैं?", hg: "Saade paani wali tube ki bhi jaanch kyon karte hain?" },
  "As a control, to see the colour without protein.": { hi: "कंट्रोल के तौर पर, यह देखने के लिए कि प्रोटीन के बिना रंग कैसा रहता है।", hg: "Control ke taur par, ye dekhne ke liye ki protein ke bina rang kaisa rehta hai." },
  "Name two protein-rich foods.": { hi: "प्रोटीन से भरपूर दो खानों के नाम बताइए।", hg: "Protein se bharpoor do khaanon ke naam bataiye." },
  "Milk and pulses (dal), also eggs, paneer, soybean.": { hi: "दूध और दालें; अंडे, पनीर और सोयाबीन भी।", hg: "Doodh aur daalein; ande, paneer aur soybean bhi." },
  "What does saliva do to boiled rice?": { hi: "लार उबले चावल के साथ क्या करती है?", hg: "Laar ubale chawal ke saath kya karti hai?" },
  "To keep plain boiled rice and chewed boiled rice in water for ten minutes, then test both with iodine for starch.": { hi: "सादे उबले चावल और चबाए हुए उबले चावल को दस मिनट पानी में रखना, फिर दोनों में आयोडीन से स्टार्च की जाँच करना।", hg: "Saade ubale chawal aur chabaaye hue ubale chawal ko das minute paani mein rakhna, phir dono mein iodine se starch ki jaanch karna." },
  "Digestion begins in the mouth": { hi: "पाचन मुँह से ही शुरू हो जाता है", hg: "Digestion muh se hi shuru ho jaata hai" },
  "Test tube A — boiled rice": { hi: "टेस्ट ट्यूब A — उबले चावल", hg: "Test tube A — ubale chawal" },
  "Test tube B — chewed boiled rice": { hi: "टेस्ट ट्यूब B — चबाए हुए उबले चावल", hg: "Test tube B — chabaaye hue ubale chawal" },
  "Put a spoonful of boiled rice into test tube A, add 5 mL of water and shake.": { hi: "टेस्ट ट्यूब A में एक चम्मच उबले चावल डालिए, 5 मिलीलीटर पानी मिलाइए और हिलाइए।", hg: "Test tube A mein ek chammach ubale chawal daaliye, 5 mL paani milaiye aur hilaiye." },
  "Rice grains in cloudy water.": { hi: "धुंधले पानी में चावल के दाने।", hg: "Dhundhle paani mein chawal ke daane." },
  "Chew another spoonful of boiled rice for two minutes, then put it into test tube B. Add 5 mL of water and shake.": { hi: "एक चम्मच उबले चावल दो मिनट तक चबाइए, फिर उसे टेस्ट ट्यूब B में डालिए। 5 मिलीलीटर पानी मिलाकर हिलाइए।", hg: "Ek chammach ubale chawal do minute tak chabaiye, phir use test tube B mein daaliye. 5 mL paani milaakar hilaiye." },
  "Chewed rice in cloudy water.": { hi: "धुंधले पानी में चबाए हुए चावल।", hg: "Dhundhle paani mein chabaaye hue chawal." },
  "While chewing, the rice gets mixed with saliva from the salivary glands.": { hi: "चबाते समय चावल में लार ग्रंथियों से निकली लार मिल जाती है।", hg: "Chabaate samay chawal mein laar granthiyon se nikli laar mil jaati hai." },
  "Leave both tubes for ten minutes (time-lapse).": { hi: "दोनों ट्यूबों को दस मिनट रखा रहने दीजिए (टाइम-लैप्स)।", hg: "Dono tubes ko das minute rakha rehne dijiye (time-lapse)." },
  "Ten minutes pass.": { hi: "दस मिनट बीत गए।", hg: "Das minute beet gaye." },
  "Add two drops of iodine solution to each tube.": { hi: "हर ट्यूब में आयोडीन घोल की दो बूँदें डालिए।", hg: "Har tube mein iodine ghol ki do boondein daaliye." },
  "Tube A turns blue-black. Tube B stays yellowish-brown, the colour of iodine.": { hi: "ट्यूब A नीली-काली हो गई। ट्यूब B पीली-भूरी ही रही, यानी आयोडीन के रंग की।", hg: "Tube A neeli-kaali ho gayi. Tube B peeli-bhoori hi rahi, yaani iodine ke rang ki." },
  "The starch in A is still there. In B the saliva has broken the starch down into sugar.": { hi: "A में स्टार्च अब भी मौजूद है। B में लार ने स्टार्च को तोड़कर शक्कर बना दिया।", hg: "A mein starch ab bhi maujood hai. B mein laar ne starch ko todkar shakkar bana diya." },
  "Plain boiled rice gave a blue-black colour with iodine; chewed rice did not.": { hi: "सादे उबले चावल ने आयोडीन से नीला-काला रंग दिया; चबाए हुए चावल ने नहीं।", hg: "Saade ubale chawal ne iodine se neela-kaala rang diya; chabaaye hue chawal ne nahi." },
  "Saliva breaks down starch into sugar. Digestion of starch begins in the mouth.": { hi: "लार स्टार्च को तोड़कर शक्कर बना देती है। स्टार्च का पाचन मुँह में ही शुरू हो जाता है।", hg: "Laar starch ko todkar shakkar bana deti hai. Starch ka digestion muh mein hi shuru ho jaata hai." },
  "In a school lab, chew only clean food given by the teacher and never taste chemicals. Iodine stains.": { hi: "स्कूल की लैब में सिर्फ़ टीचर का दिया साफ़ खाना ही चबाइए, और कोई रसायन कभी मत चखिए। आयोडीन से दाग़ लगते हैं।", hg: "School ki lab mein sirf teacher ka diya saaf khaana hi chabaiye, aur koi chemical kabhi mat chakhiye. Iodine se daag lagte hain." },
  "Which substance in saliva digests starch?": { hi: "लार में कौन-सा पदार्थ स्टार्च को पचाता है?", hg: "Laar mein kaun-sa padarth starch ko pachata hai?" },
  "The enzyme salivary amylase.": { hi: "लार का एंज़ाइम, सैलिवरी एमाइलेज़।", hg: "Laar ka enzyme, salivary amylase." },
  "Into what is starch broken down?": { hi: "स्टार्च टूटकर किसमें बदल जाता है?", hg: "Starch tootkar kismein badal jaata hai?" },
  "Sugar (maltose).": { hi: "शक्कर (माल्टोज़) में।", hg: "Shakkar (maltose) mein." },
  "Why does boiled rice taste sweet if chewed for long?": { hi: "उबले चावल देर तक चबाने पर मीठे क्यों लगते हैं?", hg: "Ubale chawal der tak chabaane par meethe kyon lagte hain?" },
  "Saliva turns its starch into sugar.": { hi: "लार उसके स्टार्च को शक्कर में बदल देती है।", hg: "Laar uske starch ko shakkar mein badal deti hai." },
  "Saliva and starch at different temperatures": { hi: "अलग-अलग तापमान पर लार और स्टार्च", hg: "Alag-alag temperature par laar aur starch" },
  "To mix starch solution with saliva, keep the tubes cold, at body temperature or in boiling water, and test them with iodine after twenty minutes.": { hi: "स्टार्च के घोल में लार मिलाना, ट्यूबों को ठंड में, शरीर के तापमान पर या उबलते पानी में रखना, और बीस मिनट बाद आयोडीन से जाँचना।", hg: "Starch ke ghol mein laar milaana, tubes ko thand mein, sharir ke temperature par ya ubalte paani mein rakhna, aur bees minute baad iodine se jaanchna." },
  "Action of salivary amylase on starch; effect of temperature": { hi: "स्टार्च पर लार के एमाइलेज़ का असर; तापमान का प्रभाव", hg: "Starch par laar ke amylase ka asar; temperature ka prabhaav" },
  "Test tube A — starch + saliva (37 °C)": { hi: "टेस्ट ट्यूब A — स्टार्च + लार (37 °C)", hg: "Test tube A — starch + laar (37 °C)" },
  "Test tube B — starch + saliva (ice)": { hi: "टेस्ट ट्यूब B — स्टार्च + लार (बर्फ़)", hg: "Test tube B — starch + laar (barf)" },
  "Test tube C — starch + water (37 °C)": { hi: "टेस्ट ट्यूब C — स्टार्च + पानी (37 °C)", hg: "Test tube C — starch + paani (37 °C)" },
  "Test tube D — starch + saliva (boiling water)": { hi: "टेस्ट ट्यूब D — स्टार्च + लार (उबलता पानी)", hg: "Test tube D — starch + laar (ubalta paani)" },
  "Add 1 mL of diluted saliva to tubes A, B and D, and 1 mL of plain water to tube C.": { hi: "ट्यूब A, B और D में 1-1 मिलीलीटर पतली लार डालिए, और ट्यूब C में 1 मिलीलीटर सादा पानी।", hg: "Tube A, B aur D mein 1-1 mL patli laar daaliye, aur tube C mein 1 mL saada paani." },
  "All four tubes look the same: cloudy, colourless.": { hi: "चारों ट्यूबें एक जैसी दिखती हैं: धुंधली और बेरंग।", hg: "Chaaron tubes ek jaisi dikhti hain: dhundhli aur berang." },
  "Stand tubes A and C in the water bath at 37 °C.": { hi: "ट्यूब A और C को 37 °C वाले वॉटर बाथ में खड़ा कीजिए।", hg: "Tube A aur C ko 37 °C wale water bath mein khada kijiye." },
  "A and C warm up to body temperature.": { hi: "A और C गरम होकर शरीर के तापमान पर आ जाती हैं।", hg: "A aur C garam hokar sharir ke temperature par aa jaati hain." },
  "37 °C is the temperature inside our mouth.": { hi: "37 °C हमारे मुँह के अंदर का तापमान है।", hg: "37 °C hamare muh ke andar ka temperature hai." },
  "Stand tube B in the ice bath and tube D in the boiling water bath.": { hi: "ट्यूब B को बर्फ़ वाले बाथ में और ट्यूब D को उबलते पानी के बाथ में खड़ा कीजिए।", hg: "Tube B ko barf wale bath mein aur tube D ko ubalte paani ke bath mein khada kijiye." },
  "B cools to about 4 °C; D heats up to nearly 100 °C.": { hi: "B ठंडी होकर लगभग 4 °C पर आ जाती है; D गरम होकर लगभग 100 °C पर।", hg: "B thandi hokar lagbhag 4 °C par aa jaati hai; D garam hokar lagbhag 100 °C par." },
  "Leave all four for twenty minutes (time-lapse).": { hi: "चारों को बीस मिनट रखा रहने दीजिए (टाइम-लैप्स)।", hg: "Chaaron ko bees minute rakha rehne dijiye (time-lapse)." },
  "Twenty minutes pass.": { hi: "बीस मिनट बीत गए।", hg: "Bees minute beet gaye." },
  "Take the tubes out and add two drops of iodine solution to each.": { hi: "ट्यूबें बाहर निकालिए और हर एक में आयोडीन घोल की दो बूँदें डालिए।", hg: "Tubes bahar nikaliye aur har ek mein iodine ghol ki do boondein daaliye." },
  "Only tube A stays yellowish-brown. B (ice), C (no saliva) and D (boiled) turn blue-black.": { hi: "सिर्फ़ ट्यूब A पीली-भूरी रही। B (बर्फ़), C (बिना लार) और D (उबली) नीली-काली हो गईं।", hg: "Sirf tube A peeli-bhoori rahi. B (barf), C (bina laar) aur D (ubli) neeli-kaali ho gayin." },
  "The enzyme in saliva digested the starch only at body temperature. In the cold it works too slowly, and boiling destroys it.": { hi: "लार के एंज़ाइम ने स्टार्च को सिर्फ़ शरीर के तापमान पर पचाया। ठंड में वह बहुत धीरे काम करता है, और उबालने से वह नष्ट हो जाता है।", hg: "Laar ke enzyme ne starch ko sirf sharir ke temperature par pachaya. Thand mein wo bahut dheere kaam karta hai, aur ubaalne se wo nasht ho jaata hai." },
  "After twenty minutes, iodine stayed yellowish-brown only in tube A (saliva at 37 °C); tubes B, C and D turned blue-black.": { hi: "बीस मिनट बाद आयोडीन सिर्फ़ ट्यूब A (37 °C पर लार) में पीला-भूरा रहा; ट्यूब B, C और D नीली-काली हो गईं।", hg: "Bees minute baad iodine sirf tube A (37 °C par laar) mein peela-bhoora raha; tube B, C aur D neeli-kaali ho gayin." },
  "Salivary amylase digests starch into sugar, and works best at body temperature. It hardly works in the cold, and heat destroys it.": { hi: "लार का एमाइलेज़ स्टार्च को पचाकर शक्कर बनाता है, और शरीर के तापमान पर सबसे अच्छा काम करता है। ठंड में यह लगभग काम नहीं करता, और गरमी इसे नष्ट कर देती है।", hg: "Laar ka amylase starch ko pachaakar shakkar banata hai, aur sharir ke temperature par sabse achha kaam karta hai. Thand mein ye lagbhag kaam nahi karta, aur garmi ise nasht kar deti hai." },
  "Use your own saliva only, and never share it. Be careful with the boiling water bath.": { hi: "सिर्फ़ अपनी ही लार इस्तेमाल कीजिए, किसी से साझा मत कीजिए। उबलते पानी के बाथ से सावधान रहिए।", hg: "Sirf apni hi laar istemaal kijiye, kisi se share mat kijiye. Ubalte paani ke bath se saavdhaan rahiye." },
  "Which tube is the control?": { hi: "कौन-सी ट्यूब कंट्रोल है?", hg: "Kaun-si tube control hai?" },
  "Tube C, with water instead of saliva.": { hi: "ट्यूब C, जिसमें लार की जगह पानी है।", hg: "Tube C, jismein laar ki jagah paani hai." },
  "Why did tube D turn blue-black?": { hi: "ट्यूब D नीली-काली क्यों हुई?", hg: "Tube D neeli-kaali kyon hui?" },
  "Boiling destroyed the enzyme, so the starch was not digested.": { hi: "उबालने से एंज़ाइम नष्ट हो गया, इसलिए स्टार्च नहीं पचा।", hg: "Ubaalne se enzyme nasht ho gaya, isliye starch nahi pacha." },
  "At what temperature does salivary amylase work best?": { hi: "लार का एमाइलेज़ किस तापमान पर सबसे अच्छा काम करता है?", hg: "Laar ka amylase kis temperature par sabse achha kaam karta hai?" },
  "About 37 °C, body temperature.": { hi: "लगभग 37 °C पर, यानी शरीर के तापमान पर।", hg: "Lagbhag 37 °C par, yaani sharir ke temperature par." },
  "Bubbles of oxygen from Hydrilla: does more light give more bubbles?": { hi: "हाइड्रिला से ऑक्सीजन के बुलबुले: क्या ज़्यादा रोशनी में ज़्यादा बुलबुले बनते हैं?", hg: "Hydrilla se oxygen ke bulbule: kya zyada roshni mein zyada bulbule bante hain?" },
  "To collect the gas given off by Hydrilla in light, count its bubbles with a lamp at different distances, and test the gas with a glowing splint.": { hi: "रोशनी में हाइड्रिला से निकली गैस जमा करना, लैंप को अलग-अलग दूरी पर रखकर बुलबुले गिनना, और सुलगती तीली से गैस की जाँच करना।", hg: "Roshni mein Hydrilla se nikli gas jama karna, lamp ko alag-alag doori par rakhkar bulbule ginna, aur sulagti teeli se gas ki jaanch karna." },
  "Photosynthesis gives out oxygen; rate and light": { hi: "प्रकाश संश्लेषण में ऑक्सीजन निकलती है; उसकी रफ़्तार और रोशनी", hg: "Photosynthesis mein oxygen nikalti hai; uski raftaar aur roshni" },
  "Put a pinch of baking soda into the beaker of water with Hydrilla.": { hi: "हाइड्रिला वाले पानी के बीकर में एक चुटकी खाने का सोडा डालिए।", hg: "Hydrilla wale paani ke beaker mein ek chutki khaane ka soda daaliye." },
  "The white powder dissolves.": { hi: "सफ़ेद पाउडर घुल जाता है।", hg: "Safed powder ghul jaata hai." },
  "Baking soda gives the water more carbon dioxide, which the plant needs for photosynthesis.": { hi: "खाने का सोडा पानी में ज़्यादा कार्बन डाइऑक्साइड देता है, जो पौधे को प्रकाश संश्लेषण के लिए चाहिए।", hg: "Khaane ka soda paani mein zyada carbon dioxide deta hai, jo paudhe ko photosynthesis ke liye chahiye." },
  "Lower a glass funnel upside down over the Hydrilla.": { hi: "काँच की कीप (फ़नल) को उलटा करके हाइड्रिला के ऊपर रखिए।", hg: "Kaanch ka funnel ulta karke Hydrilla ke upar rakhiye." },
  "The funnel covers the twigs; its stem points up, under water.": { hi: "फ़नल ने टहनियों को ढक लिया; उसकी नली ऊपर की तरफ़ है, पानी के अंदर।", hg: "Funnel ne tehniyon ko dhak liya; uski nali upar ki taraf hai, paani ke andar." },
  "Fill a test tube with water, close it with your thumb, turn it upside down and slip it over the funnel’s stem.": { hi: "एक टेस्ट ट्यूब को पानी से भरिए, अँगूठे से उसका मुँह बंद कीजिए, उलटा कीजिए और फ़नल की नली पर चढ़ा दीजिए।", hg: "Ek test tube ko paani se bhariye, angoothe se uska muh band kijiye, ulta kijiye aur funnel ki nali par chadha dijiye." },
  "The tube stands full of water over the funnel, with no air in it.": { hi: "ट्यूब पानी से भरी फ़नल पर खड़ी है, उसमें बिल्कुल हवा नहीं है।", hg: "Tube paani se bhari funnel par khadi hai, usmein bilkul hawa nahi hai." },
  "Any gas from the plant will rise into the tube and push the water down.": { hi: "पौधे से जो भी गैस निकलेगी, वह ट्यूब में ऊपर जाएगी और पानी को नीचे धकेलेगी।", hg: "Paudhe se jo bhi gas niklegi, wo tube mein upar jaayegi aur paani ko neeche dhakelegi." },
  "Switch the lamp on and set it 10 cm from the beaker. Count the bubbles that rise in one minute.": { hi: "लैंप जलाइए और उसे बीकर से 10 सेंटीमीटर दूर रखिए। एक मिनट में उठने वाले बुलबुले गिनिए।", hg: "Lamp jalaiye aur use beaker se 10 cm door rakhiye. Ek minute mein uthne wale bulbule giniye." },
  "Move the lamp to 20 cm and count the bubbles for one minute again.": { hi: "लैंप को 20 सेंटीमीटर पर ले जाइए और फिर से एक मिनट बुलबुले गिनिए।", hg: "Lamp ko 20 cm par le jaaiye aur phir se ek minute bulbule giniye." },
  "Move the lamp to 30 cm and count again.": { hi: "लैंप को 30 सेंटीमीटर पर ले जाइए और फिर गिनिए।", hg: "Lamp ko 30 cm par le jaaiye aur phir giniye." },
  "Switch the lamp off and count again.": { hi: "लैंप बंद कीजिए और फिर गिनिए।", hg: "Lamp band kijiye aur phir giniye." },
  "Hardly any bubbles rise now.": { hi: "अब मुश्किल से कोई बुलबुला उठता है।", hg: "Ab mushkil se koi bulbula uthta hai." },
  "With little light the plant makes very little food and gives out very little oxygen.": { hi: "कम रोशनी में पौधा बहुत कम भोजन बनाता है और बहुत कम ऑक्सीजन छोड़ता है।", hg: "Kam roshni mein paudha bahut kam bhojan banata hai aur bahut kam oxygen chhodta hai." },
  "Put the lamp close again and leave the set-up for three hours (time-lapse).": { hi: "लैंप को फिर पास रखिए और पूरे सेट-अप को तीन घंटे ऐसे ही रहने दीजिए (टाइम-लैप्स)।", hg: "Lamp ko phir paas rakhiye aur poore set-up ko teen ghante aise hi rehne dijiye (time-lapse)." },
  "Gas collects at the top of the test tube and pushes the water down.": { hi: "टेस्ट ट्यूब के ऊपर गैस जमा होती है और पानी को नीचे धकेल देती है।", hg: "Test tube ke upar gas jama hoti hai aur paani ko neeche dhakel deti hai." },
  "Lift the tube out with your thumb over its mouth, turn it upright and push a glowing splint into it.": { hi: "अँगूठे से मुँह बंद रखते हुए ट्यूब निकालिए, सीधा कीजिए और उसमें एक सुलगती तीली डालिए।", hg: "Angoothe se muh band rakhte hue tube nikaliye, seedha kijiye aur usmein ek sulagti teeli daaliye." },
  "The glowing splint bursts into flame.": { hi: "सुलगती तीली भभककर जल उठती है!", hg: "Sulagti teeli bhabhakkar jal uthti hai!" },
  "The gas is oxygen: oxygen makes a glowing splint flare up. Green plants give out oxygen in photosynthesis.": { hi: "यह गैस ऑक्सीजन है: ऑक्सीजन सुलगती तीली को भभका देती है। हरे पौधे प्रकाश संश्लेषण में ऑक्सीजन छोड़ते हैं।", hg: "Ye gas oxygen hai: oxygen sulagti teeli ko bhabhaka deti hai. Hare paudhe photosynthesis mein oxygen chhodte hain." },
  "Bubbles rose fastest with the lamp close and fewer as it moved away; almost none with the lamp off. The gas collected made a glowing splint burst into flame.": { hi: "लैंप पास होने पर बुलबुले सबसे तेज़ उठे, और दूर ले जाने पर कम होते गए; लैंप बंद होने पर लगभग नहीं उठे। जमा हुई गैस ने सुलगती तीली को जला दिया।", hg: "Lamp paas hone par bulbule sabse tez uthe, aur door le jaane par kam hote gaye; lamp band hone par lagbhag nahi uthe. Jama hui gas ne sulagti teeli ko jala diya." },
  "Water plants give out oxygen in light. The brighter the light, the faster the photosynthesis.": { hi: "पानी के पौधे रोशनी में ऑक्सीजन छोड़ते हैं। रोशनी जितनी तेज़, प्रकाश संश्लेषण उतना तेज़।", hg: "Paani ke paudhe roshni mein oxygen chhodte hain. Roshni jitni tez, photosynthesis utna tez." },
  "The lamp bulb gets hot: do not touch it. Keep water away from the lamp’s wire.": { hi: "लैंप का बल्ब गरम हो जाता है, उसे मत छुइए। लैंप के तार से पानी दूर रखिए।", hg: "Lamp ka bulb garam ho jaata hai, use mat chhuiye. Lamp ke taar se paani door rakhiye." },
  "Which gas is in the bubbles?": { hi: "बुलबुलों में कौन-सी गैस है?", hg: "Bulbulon mein kaun-si gas hai?" },
  "Oxygen.": { hi: "ऑक्सीजन।", hg: "Oxygen." },
  "Why did the bubbles slow down when the lamp moved away?": { hi: "लैंप दूर ले जाने पर बुलबुले कम क्यों हो गए?", hg: "Lamp door le jaane par bulbule kam kyon ho gaye?" },
  "Less light reached the plant, so it photosynthesised more slowly.": { hi: "पौधे तक कम रोशनी पहुँची, इसलिए प्रकाश संश्लेषण धीमा हो गया।", hg: "Paudhe tak kam roshni pahunchi, isliye photosynthesis dheema ho gaya." },
  "Why is baking soda added?": { hi: "खाने का सोडा क्यों डाला जाता है?", hg: "Khaane ka soda kyon daala jaata hai?" },
  "It gives the water extra carbon dioxide.": { hi: "इससे पानी में ज़्यादा कार्बन डाइऑक्साइड मिलती है।", hg: "Isse paani mein zyada carbon dioxide milti hai." },
  "About 76 bubbles in one minute.": { hi: "एक मिनट में लगभग 76 बुलबुले।", hg: "Ek minute mein lagbhag 76 bulbule." },
  "About 20 bubbles in one minute.": { hi: "एक मिनट में लगभग 20 बुलबुले।", hg: "Ek minute mein lagbhag 20 bulbule." },
  "About 10 bubbles in one minute.": { hi: "एक मिनट में लगभग 10 बुलबुले।", hg: "Ek minute mein lagbhag 10 bulbule." },
  "Bubbles stream from the cut ends of the twigs: the plant gives out a gas in light.": { hi: "टहनियों के कटे सिरों से बुलबुलों की लड़ी निकल रही है: रोशनी में पौधा एक गैस छोड़ता है।", hg: "Tehniyon ke kate siron se bulbulon ki ladi nikal rahi hai: roshni mein paudha ek gas chhodta hai." },
  "Fewer bubbles: the light reaching the plant is weaker when the lamp is farther away.": { hi: "बुलबुले कम हो गए: लैंप दूर होने पर पौधे तक पहुँचने वाली रोशनी कमज़ोर हो जाती है।", hg: "Bulbule kam ho gaye: lamp door hone par paudhe tak pahunchne wali roshni kamzor ho jaati hai." },
  "What do seeds need to sprout? Water, air and warmth": { hi: "बीजों को अंकुरित होने के लिए क्या चाहिए? पानी, हवा और गरमी", hg: "Beejon ko ankurit hone ke liye kya chahiye? Paani, hawa aur garmi" },
  "To keep moong seeds dry, on moist cotton, under water, and on moist cotton in a refrigerator, and see after three days which ones sprout.": { hi: "मूँग के बीजों को सूखा, गीली रुई पर, पानी में डुबोकर, और गीली रुई पर फ्रिज में रखना, और तीन दिन बाद देखना कि कौन-से अंकुरित होते हैं।", hg: "Moong ke beejon ko sookha, geeli rui par, paani mein dubokar, aur geeli rui par fridge mein rakhna, aur teen din baad dekhna ki kaun-se ankurit hote hain." },
  "Conditions for germination": { hi: "अंकुरण की शर्तें", hg: "Ankuran (germination) ki sharten" },
  "Dish A: leave the seeds on dry cotton. Dish B: pour a little water on the cotton, just enough to make it moist.": { hi: "डिश A: बीजों को सूखी रुई पर ही रहने दीजिए। डिश B: रुई पर थोड़ा पानी डालिए, बस इतना कि वह नम हो जाए।", hg: "Dish A: beejon ko sookhi rui par hi rehne dijiye. Dish B: rui par thoda paani daaliye, bas itna ki wo nam ho jaaye." },
  "The cotton in B turns damp and grey; A stays dry.": { hi: "B की रुई नम होकर हल्की सलेटी हो गई; A की सूखी रही।", hg: "B ki rui nam hokar halki saleti ho gayi; A ki sookhi rahi." },
  "Beaker C: pour in water until the seeds are completely under water.": { hi: "बीकर C: इतना पानी डालिए कि बीज पूरी तरह पानी में डूब जाएँ।", hg: "Beaker C: itna paani daaliye ki beej poori tarah paani mein doob jaayein." },
  "The seeds lie at the bottom under a deep layer of water.": { hi: "बीज तली में, पानी की मोटी परत के नीचे पड़े हैं।", hg: "Beej tali mein, paani ki moti parat ke neeche pade hain." },
  "Under water the seeds get very little air.": { hi: "पानी में डूबे बीजों को बहुत कम हवा मिलती है।", hg: "Paani mein doobe beejon ko bahut kam hawa milti hai." },
  "Dish D: moisten the cotton like B, then keep the dish in the refrigerator.": { hi: "डिश D: B की तरह रुई को नम कीजिए, फिर डिश को फ्रिज में रख दीजिए।", hg: "Dish D: B ki tarah rui ko nam kijiye, phir dish ko fridge mein rakh dijiye." },
  "Dish D sits in the cold refrigerator.": { hi: "डिश D ठंडे फ्रिज में रखी है।", hg: "Dish D thande fridge mein rakhi hai." },
  "Inside the refrigerator it is about 4 °C: wet, airy, but cold.": { hi: "फ्रिज के अंदर लगभग 4 °C होता है: नमी है, हवा है, पर ठंड है।", hg: "Fridge ke andar lagbhag 4 °C hota hai: nami hai, hawa hai, par thand hai." },
  "Leave all four for three days: slide the clock on.": { hi: "चारों को तीन दिन ऐसे ही रहने दीजिए: घड़ी आगे खिसकाइए।", hg: "Chaaron ko teen din aise hi rehne dijiye: ghadi aage khiskaiye." },
  "Three days pass.": { hi: "तीन दिन बीत गए।", hg: "Teen din beet gaye." },
  "Take D out of the refrigerator and compare the seeds in A, B, C and D.": { hi: "D को फ्रिज से निकालिए और A, B, C और D के बीजों की तुलना कीजिए।", hg: "D ko fridge se nikaliye aur A, B, C aur D ke beejon ki tulna kijiye." },
  "Only the seeds in B have sprouted: a white root has come out of each. Those in A are dry and unchanged; those in C and D have swollen but not sprouted.": { hi: "सिर्फ़ B के बीज अंकुरित हुए: हर बीज से एक सफ़ेद जड़ निकल आई है। A के बीज सूखे और वैसे ही हैं; C और D के बीज फूल तो गए, पर अंकुरित नहीं हुए।", hg: "Sirf B ke beej ankurit hue: har beej se ek safed jad nikal aayi hai. A ke beej sookhe aur waise hi hain; C aur D ke beej phool to gaye, par ankurit nahi hue." },
  "Seeds need water, air and warmth to germinate. A had no water, C had no air, and D was too cold.": { hi: "बीजों को अंकुरित होने के लिए पानी, हवा और गरमी चाहिए। A को पानी नहीं मिला, C को हवा नहीं मिली, और D बहुत ठंडा था।", hg: "Beejon ko ankurit hone ke liye paani, hawa aur garmi chahiye. A ko paani nahi mila, C ko hawa nahi mili, aur D bahut thanda tha." },
  "After three days only the seeds on moist cotton at room temperature (B) sprouted. Dry seeds (A), seeds under water (C) and seeds in the refrigerator (D) did not.": { hi: "तीन दिन बाद सिर्फ़ कमरे के तापमान पर गीली रुई वाले बीज (B) अंकुरित हुए। सूखे बीज (A), पानी में डूबे बीज (C) और फ्रिज वाले बीज (D) नहीं हुए।", hg: "Teen din baad sirf kamre ke temperature par geeli rui wale beej (B) ankurit hue. Sookhe beej (A), paani mein doobe beej (C) aur fridge wale beej (D) nahi hue." },
  "Seeds need water, air and a suitable warm temperature to germinate.": { hi: "अंकुरित होने के लिए बीजों को पानी, हवा और सही गरम तापमान चाहिए।", hg: "Ankurit hone ke liye beejon ko paani, hawa aur sahi garam temperature chahiye." },
  "Wash your hands after handling seeds; do not eat seeds kept in the lab.": { hi: "बीज छूने के बाद हाथ धोइए; लैब में रखे बीज मत खाइए।", hg: "Beej chhoone ke baad haath dhoiye; lab mein rakhe beej mat khaiye." },
  "Why did the seeds in C not germinate?": { hi: "C के बीज अंकुरित क्यों नहीं हुए?", hg: "C ke beej ankurit kyon nahi hue?" },
  "They were under water and got no air.": { hi: "वे पानी में डूबे थे और उन्हें हवा नहीं मिली।", hg: "Wo paani mein doobe the aur unhe hawa nahi mili." },
  "Which dish was the control?": { hi: "कौन-सी डिश कंट्रोल थी?", hg: "Kaun-si dish control thi?" },
  "B: water, air and warmth.": { hi: "B: पानी, हवा और गरमी तीनों।", hg: "B: paani, hawa aur garmi teeno." },
  "What comes out of a seed first when it germinates?": { hi: "अंकुरित होते समय बीज से सबसे पहले क्या निकलता है?", hg: "Ankurit hote samay beej se sabse pehle kya nikalta hai?" },
  "The root (radicle).": { hi: "जड़ (मूलांकुर, रेडिकल)।", hg: "Jad (radicle)." },
  "Raisins in water and in sugar solution: osmosis": { hi: "पानी और चीनी के घोल में किशमिश: परासरण (ऑस्मोसिस)", hg: "Paani aur cheeni ke ghol mein kishmish: osmosis" },
  "To keep dry raisins in plain water and in a strong sugar solution, see which swell, and then move the swollen ones into the sugar solution.": { hi: "सूखी किशमिश को सादे पानी में और गाढ़े चीनी के घोल में रखना, देखना कि कौन-सी फूलती है, और फिर फूली किशमिश को चीनी के घोल में डालना।", hg: "Sookhi kishmish ko saade paani mein aur gaadhe cheeni ke ghol mein rakhna, dekhna ki kaun-si phoolti hai, aur phir phooli kishmish ko cheeni ke ghol mein daalna." },
  "Osmosis: endosmosis and exosmosis": { hi: "परासरण: अंतःपरासरण और बहिःपरासरण", hg: "Osmosis: endosmosis aur exosmosis" },
  "Beaker A — plain water": { hi: "बीकर A — सादा पानी", hg: "Beaker A — saada paani" },
  "Beaker B — strong sugar solution": { hi: "बीकर B — गाढ़ा चीनी का घोल", hg: "Beaker B — gaadha cheeni ka ghol" },
  "Drop six raisins into beaker A, which has plain water.": { hi: "सादे पानी वाले बीकर A में छह किशमिश डालिए।", hg: "Saade paani wale beaker A mein chhah kishmish daaliye." },
  "The wrinkled raisins sink to the bottom.": { hi: "सिकुड़ी हुई किशमिश तली में बैठ जाती है।", hg: "Sikudi hui kishmish tali mein baith jaati hai." },
  "Drop six raisins into beaker B, which has a strong sugar solution.": { hi: "गाढ़े चीनी के घोल वाले बीकर B में छह किशमिश डालिए।", hg: "Gaadhe cheeni ke ghol wale beaker B mein chhah kishmish daaliye." },
  "These raisins also sink.": { hi: "ये किशमिश भी डूब जाती है।", hg: "Ye kishmish bhi doob jaati hai." },
  "Leave them for four hours: slide the clock on.": { hi: "इन्हें चार घंटे ऐसे ही रहने दीजिए: घड़ी आगे खिसकाइए।", hg: "Inhe chaar ghante aise hi rehne dijiye: ghadi aage khiskaiye." },
  "The raisins in water grow plump and smooth. Those in the sugar solution stay small and wrinkled.": { hi: "पानी वाली किशमिश फूलकर गोल-मटोल और चिकनी हो जाती है। चीनी के घोल वाली छोटी और सिकुड़ी ही रहती है।", hg: "Paani wali kishmish phoolkar gol-matol aur chikni ho jaati hai. Cheeni ke ghol wali chhoti aur sikudi hi rehti hai." },
  "Compare them with the dry raisins.": { hi: "इनकी तुलना सूखी किशमिश से कीजिए।", hg: "Inki tulna sookhi kishmish se kijiye." },
  "The raisins from water are nearly twice as big as the dry ones; the others look like the dry ones.": { hi: "पानी वाली किशमिश सूखी किशमिश से लगभग दोगुनी बड़ी है; बाकी सूखी जैसी ही दिखती है।", hg: "Paani wali kishmish sookhi kishmish se lagbhag doguni badi hai; baaki sookhi jaisi hi dikhti hai." },
  "Water passed into the raisins in plain water through their skins (endosmosis). The sugar solution outside was stronger than the juice inside, so no water went in.": { hi: "सादे पानी में रखी किशमिश के अंदर उसके छिलके से होकर पानी चला गया (अंतःपरासरण)। चीनी वाला घोल अंदर के रस से ज़्यादा गाढ़ा था, इसलिए वहाँ पानी अंदर नहीं गया।", hg: "Saade paani mein rakhi kishmish ke andar uske chhilke se hokar paani chala gaya (endosmosis). Cheeni wala ghol andar ke ras se zyada gaadha tha, isliye wahan paani andar nahi gaya." },
  "Now move the swollen raisins from beaker A into the sugar solution and wait four more hours.": { hi: "अब बीकर A की फूली किशमिश को चीनी के घोल में डालिए और चार घंटे और रुकिए।", hg: "Ab beaker A ki phooli kishmish ko cheeni ke ghol mein daaliye aur chaar ghante aur rukiye." },
  "They shrink and wrinkle again.": { hi: "वे फिर से सिकुड़कर झुर्रीदार हो जाती हैं।", hg: "Wo phir se sikudkar jhurridaar ho jaati hain." },
  "Now the solution outside is stronger: water leaves the raisins (exosmosis). Water always moves from where it is more to where it is less, through the skin.": { hi: "अब बाहर का घोल ज़्यादा गाढ़ा है: पानी किशमिश से बाहर निकल जाता है (बहिःपरासरण)। पानी हमेशा छिलके के पार, जहाँ ज़्यादा है वहाँ से, जहाँ कम है वहाँ जाता है।", hg: "Ab bahar ka ghol zyada gaadha hai: paani kishmish se bahar nikal jaata hai (exosmosis). Paani hamesha chhilke ke paar, jahan zyada hai wahan se, jahan kam hai wahan jaata hai." },
  "Dry raisins swelled in plain water but not in strong sugar solution; the swollen ones shrank again in the sugar solution.": { hi: "सूखी किशमिश सादे पानी में फूल गई, पर गाढ़े चीनी के घोल में नहीं; फूली हुई किशमिश चीनी के घोल में फिर सिकुड़ गई।", hg: "Sookhi kishmish saade paani mein phool gayi, par gaadhe cheeni ke ghol mein nahi; phooli hui kishmish cheeni ke ghol mein phir sikud gayi." },
  "Water moves into or out of cells by osmosis, depending on whether the solution outside is weaker or stronger than the cell sap.": { hi: "परासरण से पानी कोशिकाओं के अंदर या बाहर जाता है। यह इस पर निर्भर है कि बाहर का घोल कोशिका के रस से पतला है या गाढ़ा।", hg: "Osmosis se paani cells ke andar ya bahar jaata hai. Ye is par nirbhar hai ki bahar ka ghol cell ke ras se patla hai ya gaadha." },
  "Do not eat the raisins used in the lab.": { hi: "लैब में इस्तेमाल हुई किशमिश मत खाइए।", hg: "Lab mein istemaal hui kishmish mat khaiye." },
  "What is osmosis?": { hi: "परासरण (ऑस्मोसिस) क्या है?", hg: "Osmosis kya hai?" },
  "The movement of water through a membrane from a weaker to a stronger solution.": { hi: "एक झिल्ली के पार पानी का पतले घोल से गाढ़े घोल की तरफ़ जाना।", hg: "Ek jhilli ke paar paani ka patle ghol se gaadhe ghol ki taraf jaana." },
  "Why did the raisins swell in water?": { hi: "किशमिश पानी में क्यों फूली?", hg: "Kishmish paani mein kyon phooli?" },
  "Water entered them by endosmosis.": { hi: "अंतःपरासरण से पानी उनके अंदर चला गया।", hg: "Endosmosis se paani unke andar chala gaya." },
  "What happened in the sugar solution?": { hi: "चीनी के घोल में क्या हुआ?", hg: "Cheeni ke ghol mein kya hua?" },
  "Water left the raisins (exosmosis), so they shrank.": { hi: "पानी किशमिश से बाहर निकल गया (बहिःपरासरण), इसलिए वे सिकुड़ गईं।", hg: "Paani kishmish se bahar nikal gaya (exosmosis), isliye wo sikud gayin." },
  "Germinating seeds give out carbon dioxide": { hi: "अंकुरित बीज कार्बन डाइऑक्साइड छोड़ते हैं", hg: "Ankurit beej carbon dioxide chhodte hain" },
  "To close sprouting seeds in a flask with a small tube of potassium hydroxide, and see coloured water climb a bent tube as the gas is taken up.": { hi: "अंकुरित बीजों को एक फ़्लास्क में पोटैशियम हाइड्रॉक्साइड की छोटी ट्यूब के साथ बंद करना, और गैस सोखे जाने पर रंगीन पानी को मुड़ी हुई नली में चढ़ते देखना।", hg: "Ankurit beejon ko ek flask mein potassium hydroxide ki chhoti tube ke saath band karna, aur gas sokhe jaane par rangeen paani ko mudi hui nali mein chadhte dekhna." },
  "Respiration in seeds": { hi: "बीजों में श्वसन", hg: "Beejon mein respiration (shvasan)" },
  "Hang the small tube of potassium hydroxide inside flask A with a thread. Flask B gets none.": { hi: "पोटैशियम हाइड्रॉक्साइड की छोटी ट्यूब को धागे से फ़्लास्क A के अंदर लटकाइए। फ़्लास्क B में कुछ नहीं।", hg: "Potassium hydroxide ki chhoti tube ko dhaage se flask A ke andar latkaiye. Flask B mein kuch nahi." },
  "The small tube hangs above the seeds in flask A.": { hi: "फ़्लास्क A में छोटी ट्यूब बीजों के ऊपर लटक रही है।", hg: "Flask A mein chhoti tube beejon ke upar latak rahi hai." },
  "Potassium hydroxide takes up carbon dioxide gas.": { hi: "पोटैशियम हाइड्रॉक्साइड कार्बन डाइऑक्साइड गैस सोख लेता है।", hg: "Potassium hydroxide carbon dioxide gas sokh leta hai." },
  "Close both flasks with corks carrying bent glass tubes, dip the free ends in the coloured water, and seal the corks with Vaseline.": { hi: "दोनों फ़्लास्कों को ऐसे कॉर्क से बंद कीजिए जिनमें काँच की मुड़ी नली लगी हो, नली के खुले सिरे रंगीन पानी में डुबोइए, और कॉर्क को वैसलीन से सील कीजिए।", hg: "Dono flasks ko aise cork se band kijiye jinmein kaanch ki mudi nali lagi ho, nali ke khule sire rangeen paani mein duboiye, aur cork ko Vaseline se seal kijiye." },
  "Each flask is now airtight, joined by its tube to a beaker of coloured water.": { hi: "अब हर फ़्लास्क हवा-बंद है और अपनी नली से रंगीन पानी के बीकर से जुड़ा है।", hg: "Ab har flask hawa-band hai aur apni nali se rangeen paani ke beaker se juda hai." },
  "Mark the level of the water in each bent tube.": { hi: "हर मुड़ी नली में पानी का लेवल निशान लगाकर चिह्नित कीजिए।", hg: "Har mudi nali mein paani ka level nishaan lagaakar mark kijiye." },
  "Both levels are marked.": { hi: "दोनों लेवल पर निशान लग गए।", hg: "Dono level par nishaan lag gaye." },
  "Leave them for two hours: slide the clock on.": { hi: "इन्हें दो घंटे ऐसे ही रहने दीजिए: घड़ी आगे खिसकाइए।", hg: "Inhe do ghante aise hi rehne dijiye: ghadi aage khiskaiye." },
  "The coloured water climbs up the tube from flask A. In the tube from flask B it stays at the mark.": { hi: "फ़्लास्क A की नली में रंगीन पानी ऊपर चढ़ने लगता है। फ़्लास्क B की नली में वह निशान पर ही रहता है।", hg: "Flask A ki nali mein rangeen paani upar chadhne lagta hai. Flask B ki nali mein wo nishaan par hi rehta hai." },
  "Compare the two tubes.": { hi: "दोनों नलियों की तुलना कीजिए।", hg: "Dono naliyon ki tulna kijiye." },
  "In A the water has risen several centimetres; in B it has not moved.": { hi: "A में पानी कई सेंटीमीटर चढ़ गया है; B में बिल्कुल नहीं हिला।", hg: "A mein paani kai centimetre chadh gaya hai; B mein bilkul nahi hila." },
  "The seeds take in oxygen and give out the same amount of carbon dioxide. In A the potassium hydroxide removes that carbon dioxide, so the air inside shrinks and water is pushed in. In B the carbon dioxide stays, so nothing changes.": { hi: "बीज ऑक्सीजन लेते हैं और उतनी ही कार्बन डाइऑक्साइड छोड़ते हैं। A में पोटैशियम हाइड्रॉक्साइड वह कार्बन डाइऑक्साइड हटा देता है, इसलिए अंदर की हवा कम हो जाती है और पानी अंदर धकेला जाता है। B में कार्बन डाइऑक्साइड वहीं रहती है, इसलिए कुछ नहीं बदलता।", hg: "Beej oxygen lete hain aur utni hi carbon dioxide chhodte hain. A mein potassium hydroxide wo carbon dioxide hata deta hai, isliye andar ki hawa kam ho jaati hai aur paani andar dhakela jaata hai. B mein carbon dioxide wahin rehti hai, isliye kuch nahi badalta." },
  "Water rose in the tube of the flask with potassium hydroxide, not in the flask without it.": { hi: "पोटैशियम हाइड्रॉक्साइड वाले फ़्लास्क की नली में पानी चढ़ा, बिना उसके वाले में नहीं।", hg: "Potassium hydroxide wale flask ki nali mein paani chadha, bina uske wale mein nahi." },
  "Germinating seeds respire: they give out carbon dioxide.": { hi: "अंकुरित बीज श्वसन करते हैं: वे कार्बन डाइऑक्साइड छोड़ते हैं।", hg: "Ankurit beej respiration karte hain: wo carbon dioxide chhodte hain." },
  "Potassium hydroxide is caustic. Handle the small tube carefully and keep it upright.": { hi: "पोटैशियम हाइड्रॉक्साइड त्वचा जलाता है। छोटी ट्यूब सावधानी से पकड़िए और सीधी रखिए।", hg: "Potassium hydroxide skin jalaata hai. Chhoti tube saavdhaani se pakadiye aur seedhi rakhiye." },
  "Why does the water rise in tube A?": { hi: "नली A में पानी क्यों चढ़ता है?", hg: "Nali A mein paani kyon chadhta hai?" },
  "KOH absorbs the carbon dioxide given out, so the gas inside decreases.": { hi: "KOH निकली हुई कार्बन डाइऑक्साइड सोख लेता है, इसलिए अंदर की गैस कम हो जाती है।", hg: "KOH nikli hui carbon dioxide sokh leta hai, isliye andar ki gas kam ho jaati hai." },
  "Why is flask B set up?": { hi: "फ़्लास्क B क्यों रखा जाता है?", hg: "Flask B kyon rakha jaata hai?" },
  "As a control: without KOH the level does not change.": { hi: "कंट्रोल के लिए: KOH के बिना लेवल नहीं बदलता।", hg: "Control ke liye: KOH ke bina level nahi badalta." },
  "Why are the corks sealed with Vaseline?": { hi: "कॉर्क को वैसलीन से सील क्यों करते हैं?", hg: "Cork ko Vaseline se seal kyon karte hain?" },
  "To make the flasks airtight.": { hi: "फ़्लास्कों को हवा-बंद करने के लिए।", hg: "Flasks ko hawa-band karne ke liye." },
  "Shoots bend towards light, roots grow down": { hi: "तने रोशनी की तरफ़ मुड़ते हैं, जड़ें नीचे बढ़ती हैं", hg: "Tane roshni ki taraf mudte hain, jadein neeche badhti hain" },
  "To keep bean seedlings on a flask of water in a box open towards the light, watch the shoots bend, then turn the flask round.": { hi: "पानी के फ़्लास्क पर रखे सेम के अंकुरों को एक तरफ़ से खुले डिब्बे में रोशनी की ओर रखना, तनों को मुड़ते देखना, फिर फ़्लास्क को घुमा देना।", hg: "Paani ke flask par rakhe sem ke ankuron ko ek taraf se khule dibbe mein roshni ki or rakhna, tanon ko mudte dekhna, phir flask ko ghuma dena." },
  "Phototropism and geotropism": { hi: "प्रकाशानुवर्तन और गुरुत्वानुवर्तन (फ़ोटोट्रॉपिज़्म और जियोट्रॉपिज़्म)", hg: "Phototropism aur geotropism" },
  "Put the flask with the bean seedlings inside the box. The open side of the box faces the window.": { hi: "सेम के अंकुरों वाले फ़्लास्क को डिब्बे के अंदर रखिए। डिब्बे की खुली तरफ़ खिड़की की ओर है।", hg: "Sem ke ankuron wale flask ko dibbe ke andar rakhiye. Dibbe ki khuli taraf khidki ki or hai." },
  "Light reaches the seedlings from one side only.": { hi: "अंकुरों तक रोशनी सिर्फ़ एक तरफ़ से पहुँचती है।", hg: "Ankuron tak roshni sirf ek taraf se pahunchti hai." },
  "Leave it for two days: slide the clock on 48 hours.": { hi: "इसे दो दिन ऐसे ही रहने दीजिए: घड़ी को 48 घंटे आगे खिसकाइए।", hg: "Ise do din aise hi rehne dijiye: ghadi ko 48 ghante aage khiskaiye." },
  "The shoots grow longer.": { hi: "तने लंबे हो जाते हैं।", hg: "Tane lambe ho jaate hain." },
  "Look at the seedlings.": { hi: "अंकुरों को देखिए।", hg: "Ankuron ko dekhiye." },
  "The shoots have bent towards the open side, where the light comes from. The roots grow straight down into the water.": { hi: "तने खुली तरफ़ मुड़ गए हैं, जहाँ से रोशनी आती है। जड़ें सीधी नीचे पानी में बढ़ रही हैं।", hg: "Tane khuli taraf mud gaye hain, jahan se roshni aati hai. Jadein seedhi neeche paani mein badh rahi hain." },
  "Shoots grow towards light (phototropism); roots grow towards the pull of gravity (geotropism).": { hi: "तने रोशनी की ओर बढ़ते हैं (प्रकाशानुवर्तन); जड़ें गुरुत्व के खिंचाव की ओर, यानी नीचे बढ़ती हैं (गुरुत्वानुवर्तन)।", hg: "Tane roshni ki or badhte hain (phototropism); jadein gravity ke khinchaav ki or, yaani neeche badhti hain (geotropism)." },
  "Turn the flask round, so the shoots lean away from the light, and leave it for two more days.": { hi: "फ़्लास्क को घुमा दीजिए, ताकि तने रोशनी से उलटी तरफ़ झुके हों, और दो दिन और रहने दीजिए।", hg: "Flask ko ghuma dijiye, taaki tane roshni se ulti taraf jhuke hon, aur do din aur rehne dijiye." },
  "The shoots keep growing.": { hi: "तने बढ़ते रहते हैं।", hg: "Tane badhte rehte hain." },
  "Look at the seedlings again.": { hi: "अंकुरों को फिर से देखिए।", hg: "Ankuron ko phir se dekhiye." },
  "The new growth has bent back towards the light, so each shoot has an S-shaped curve. The roots still point down.": { hi: "नई बढ़त फिर रोशनी की तरफ़ मुड़ गई है, इसलिए हर तने में S जैसा मोड़ बन गया। जड़ें अब भी नीचे की ओर हैं।", hg: "Nayi badhat phir roshni ki taraf mud gayi hai, isliye har tane mein S jaisa mod ban gaya. Jadein ab bhi neeche ki or hain." },
  "The growing tip always turns towards light. Cells on the shaded side grow longer, so the shoot bends towards the light (the hormone auxin collects on the shaded side).": { hi: "बढ़ता हुआ सिरा हमेशा रोशनी की तरफ़ मुड़ता है। छाया वाली तरफ़ की कोशिकाएँ ज़्यादा लंबी होती हैं, इसलिए तना रोशनी की ओर झुक जाता है (हॉर्मोन ऑक्सिन छाया वाली तरफ़ जमा होता है)।", hg: "Badhta hua sira hamesha roshni ki taraf mudta hai. Chhaya wali taraf ki cells zyada lambi hoti hain, isliye tana roshni ki or jhuk jaata hai (hormone auxin chhaya wali taraf jama hota hai)." },
  "In light from one side the shoots bent towards the light; after turning the flask they bent back towards it. The roots always grew downwards.": { hi: "एक तरफ़ की रोशनी में तने रोशनी की ओर मुड़े; फ़्लास्क घुमाने के बाद वे फिर उसी की ओर मुड़ गए। जड़ें हमेशा नीचे की ओर बढ़ीं।", hg: "Ek taraf ki roshni mein tane roshni ki or mude; flask ghumaane ke baad wo phir usi ki or mud gaye. Jadein hamesha neeche ki or badhin." },
  "Shoots respond to light by bending towards it, and roots respond to gravity by growing down. These growth movements are tropisms.": { hi: "तने रोशनी की ओर मुड़कर उसका जवाब देते हैं, और जड़ें नीचे बढ़कर गुरुत्व का। बढ़ने से होने वाली ऐसी गतियों को अनुवर्तन (ट्रॉपिज़्म) कहते हैं।", hg: "Tane roshni ki or mudkar uska jawab dete hain, aur jadein neeche badhkar gravity ka. Badhne se hone wali aisi gatiyon ko tropism kehte hain." },
  "Handle the glass flask and wire mesh with care.": { hi: "काँच के फ़्लास्क और तार की जाली को सावधानी से पकड़िए।", hg: "Kaanch ke flask aur taar ki jaali ko saavdhaani se pakadiye." },
  "What is phototropism?": { hi: "प्रकाशानुवर्तन (फ़ोटोट्रॉपिज़्म) क्या है?", hg: "Phototropism kya hai?" },
  "The bending of a plant part in response to light.": { hi: "रोशनी के कारण पौधे के किसी हिस्से का मुड़ना।", hg: "Roshni ke kaaran paudhe ke kisi hisse ka mudna." },
  "Which hormone causes the bending?": { hi: "कौन-सा हॉर्मोन मुड़ने की वजह बनता है?", hg: "Kaun-sa hormone mudne ki wajah banta hai?" },
  "Auxin.": { hi: "ऑक्सिन।", hg: "Auxin." },
  "How do roots respond to gravity?": { hi: "जड़ें गुरुत्व पर कैसी प्रतिक्रिया करती हैं?", hg: "Jadein gravity par kaisi pratikriya karti hain?" },
  "They grow downwards (positive geotropism).": { hi: "वे नीचे की ओर बढ़ती हैं (धनात्मक गुरुत्वानुवर्तन)।", hg: "Wo neeche ki or badhti hain (positive geotropism)." },
  "Put two or three drops of dilute iodine solution on the slice of raw potato.": { hi: "कच्चे आलू के टुकड़े पर पतले आयोडीन घोल की दो-तीन बूँदें डालिए।", hg: "Kachche aloo ke tukde par patle iodine ghol ki do-teen boondein daaliye." },
  "Now put two or three drops on the boiled rice.": { hi: "अब उबले चावल पर दो-तीन बूँदें डालिए।", hg: "Ab ubale chawal par do-teen boondein daaliye." },
  "Put a few drops on the piece of bread.": { hi: "ब्रेड के टुकड़े पर कुछ बूँदें डालिए।", hg: "Bread ke tukde par kuch boondein daaliye." },
  "Put a few drops on the apple slice.": { hi: "सेब की फाँक पर कुछ बूँदें डालिए।", hg: "Seb ki phaank par kuch boondein daaliye." },
  "Put a few drops on the cucumber slice.": { hi: "खीरे के टुकड़े पर कुछ बूँदें डालिए।", hg: "Kheere ke tukde par kuch boondein daaliye." },
  "The brown iodine turns blue-black on the potato.": { hi: "आलू पर भूरा आयोडीन नीला-काला हो जाता है।", hg: "Aloo par bhoora iodine neela-kaala ho jaata hai." },
  "The rice grains turn blue-black.": { hi: "चावल के दाने नीले-काले हो जाते हैं।", hg: "Chawal ke daane neele-kaale ho jaate hain." },
  "The bread turns blue-black.": { hi: "ब्रेड नीली-काली हो जाती है।", hg: "Bread neeli-kaali ho jaati hai." },
  "The iodine stays yellowish-brown on the apple (perhaps a faint dark tinge).": { hi: "सेब पर आयोडीन पीला-भूरा ही रहता है (शायद हल्की-सी गहरी झलक)।", hg: "Seb par iodine peela-bhoora hi rehta hai (shayad halki-si gehri jhalak)." },
  "The iodine stays yellowish-brown on the cucumber.": { hi: "खीरे पर आयोडीन पीला-भूरा ही रहता है।", hg: "Kheere par iodine peela-bhoora hi rehta hai." },
  "A blue-black colour means starch is present. Potato stores a lot of starch.": { hi: "नीला-काला रंग मतलब स्टार्च मौजूद है। आलू में बहुत सारा स्टार्च जमा रहता है।", hg: "Neela-kaala rang matlab starch maujood hai. Aloo mein bahut saara starch jama rehta hai." },
  "Rice is mostly starch, a carbohydrate that gives us energy.": { hi: "चावल में ज़्यादातर स्टार्च होता है, यानी ऊर्जा देने वाला कार्बोहाइड्रेट।", hg: "Chawal mein zyadatar starch hota hai, yaani energy dene wala carbohydrate." },
  "Bread is made from wheat flour, which is rich in starch.": { hi: "ब्रेड गेहूँ के आटे से बनती है, जिसमें ख़ूब स्टार्च होता है।", hg: "Bread gehun ke aate se banti hai, jismein khoob starch hota hai." },
  "A ripe apple has turned almost all its starch into sugar, so there is little or no starch.": { hi: "पके सेब का लगभग सारा स्टार्च शक्कर में बदल चुका होता है, इसलिए उसमें स्टार्च बहुत कम या बिल्कुल नहीं होता।", hg: "Pake seb ka lagbhag saara starch shakkar mein badal chuka hota hai, isliye usmein starch bahut kam ya bilkul nahi hota." },
  "Cucumber is mostly water; it has no starch.": { hi: "खीरे में ज़्यादातर पानी होता है; उसमें स्टार्च नहीं होता।", hg: "Kheere mein zyadatar paani hota hai; usmein starch nahi hota." },
  "carbon dioxide + water → glucose (→ starch) + oxygen, in light, with chlorophyll": { hi: "कार्बन डाइऑक्साइड + पानी → ग्लूकोज़ (→ स्टार्च) + ऑक्सीजन; रोशनी में, क्लोरोफ़िल की मदद से", hg: "carbon dioxide + paani → glucose (→ starch) + oxygen; roshni mein, chlorophyll ki madad se" },
  "carbon dioxide + water → glucose + oxygen (in sunlight, only where there is chlorophyll)": { hi: "कार्बन डाइऑक्साइड + पानी → ग्लूकोज़ + ऑक्सीजन (धूप में, सिर्फ़ जहाँ क्लोरोफ़िल हो)", hg: "carbon dioxide + paani → glucose + oxygen (dhoop mein, sirf jahan chlorophyll ho)" },
  "carbon dioxide + water → glucose + oxygen; KOH removes CO₂ (2KOH + CO₂ → K₂CO₃ + H₂O)": { hi: "कार्बन डाइऑक्साइड + पानी → ग्लूकोज़ + ऑक्सीजन; KOH, CO₂ को हटा देता है (2KOH + CO₂ → K₂CO₃ + H₂O)", hg: "carbon dioxide + paani → glucose + oxygen; KOH, CO₂ ko hata deta hai (2KOH + CO₂ → K₂CO₃ + H₂O)" },
  "water from the roots → up the xylem → out of the stomata as water vapour": { hi: "जड़ों से पानी → ज़ाइलम में ऊपर → स्टोमेटा से भाप बनकर बाहर", hg: "jadon se paani → xylem mein upar → stomata se bhaap bankar bahar" },
  "roots → xylem in the stem → veins of leaves and petals": { hi: "जड़ें → तने का ज़ाइलम → पत्तियों और पंखुड़ियों की नसें", hg: "jadein → tane ka xylem → pattiyon aur pankhudiyon ki nasein" },
  "water + dye rise together": { hi: "पानी और रंग साथ-साथ चढ़ते हैं", hg: "paani aur rang saath-saath chadhte hain" },
  "sunlight + water (+ carbon dioxide) → food → healthy growth": { hi: "धूप + पानी (+ कार्बन डाइऑक्साइड) → भोजन → स्वस्थ बढ़त", hg: "dhoop + paani (+ carbon dioxide) → bhojan → swasth badhat" },
  "starch + iodine (brown) → blue-black": { hi: "स्टार्च + आयोडीन (भूरा) → नीला-काला", hg: "starch + iodine (bhoora) → neela-kaala" },
  "no starch: iodine stays yellowish-brown": { hi: "स्टार्च नहीं: आयोडीन पीला-भूरा ही रहता है", hg: "starch nahi: iodine peela-bhoora hi rehta hai" },
  "fat + paper → lasting oily, translucent patch": { hi: "वसा + कागज़ → हमेशा रहने वाला, चिकना पारभासी धब्बा", hg: "fat + kaagaz → hamesha rehne wala, chikna translucent dhabba" },
  "water patch → dries up": { hi: "पानी का धब्बा → सूख जाता है", hg: "paani ka dhabba → sookh jaata hai" },
  "protein + copper sulphate + sodium hydroxide → violet": { hi: "प्रोटीन + कॉपर सल्फ़ेट + सोडियम हाइड्रॉक्साइड → बैंगनी", hg: "protein + copper sulphate + sodium hydroxide → baingani" },
  "no protein: light blue (copper hydroxide)": { hi: "प्रोटीन नहीं: हल्का नीला (कॉपर हाइड्रॉक्साइड)", hg: "protein nahi: halka neela (copper hydroxide)" },
  "starch —(salivary amylase, in saliva)→ sugar (maltose)": { hi: "स्टार्च —(लार का एमाइलेज़)→ शक्कर (माल्टोज़)", hg: "starch —(laar ka amylase)→ shakkar (maltose)" },
  "starch —(salivary amylase, 37 °C)→ maltose": { hi: "स्टार्च —(लार का एमाइलेज़, 37 °C)→ माल्टोज़", hg: "starch —(laar ka amylase, 37 °C)→ maltose" },
  "cold: very slow · boiling: enzyme destroyed": { hi: "ठंड: बहुत धीमा · उबालने पर: एंज़ाइम नष्ट", hg: "thand: bahut dheema · ubaalne par: enzyme nasht" },
  "carbon dioxide + water → glucose + oxygen (bubbles), in light": { hi: "कार्बन डाइऑक्साइड + पानी → ग्लूकोज़ + ऑक्सीजन (बुलबुले), रोशनी में", hg: "carbon dioxide + paani → glucose + oxygen (bulbule), roshni mein" },
  "water + air (oxygen) + warmth → germination": { hi: "पानी + हवा (ऑक्सीजन) + गरमी → अंकुरण", hg: "paani + hawa (oxygen) + garmi → ankuran" },
  "water moves through a membrane from a weaker solution to a stronger one (osmosis)": { hi: "पानी झिल्ली के पार पतले घोल से गाढ़े घोल की तरफ़ जाता है (परासरण)", hg: "paani jhilli ke paar patle ghol se gaadhe ghol ki taraf jaata hai (osmosis)" },
  "in water → swell (endosmosis) · in sugar solution → shrink (exosmosis)": { hi: "पानी में → फूलना (अंतःपरासरण) · चीनी के घोल में → सिकुड़ना (बहिःपरासरण)", hg: "paani mein → phoolna (endosmosis) · cheeni ke ghol mein → sikudna (exosmosis)" },
  "glucose + oxygen → carbon dioxide + water + energy; KOH absorbs CO₂": { hi: "ग्लूकोज़ + ऑक्सीजन → कार्बन डाइऑक्साइड + पानी + ऊर्जा; KOH, CO₂ सोख लेता है", hg: "glucose + oxygen → carbon dioxide + paani + energy; KOH, CO₂ sokh leta hai" },
  "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + energy": { hi: "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ऊर्जा", hg: "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + energy" },
  "shoot → towards light (positive phototropism) · root → down (positive geotropism)": { hi: "तना → रोशनी की ओर (धनात्मक प्रकाशानुवर्तन) · जड़ → नीचे (धनात्मक गुरुत्वानुवर्तन)", hg: "tana → roshni ki or (positive phototropism) · jad → neeche (positive geotropism)" },
  "(C₆H₁₀O₅)ₙ + H₂O → maltose": { hi: "(C₆H₁₀O₅)ₙ + H₂O → माल्टोज़", hg: "(C₆H₁₀O₅)ₙ + H₂O → maltose" },
};
